-- ============================================================================
-- 0027_bestiary_monster_tokens_part2of3.sql
--
-- Full SRD 5.1 bestiary (~327 monsters, CC-BY-4.0) as 'monster' tokens with
-- full statblocks + first-letter monogram placeholder art. Run all 3 parts,
-- in any order. Idempotent: skips a monster you already have by the same name.
-- Attribution: D&D 5.1 SRD, CC-BY-4.0 (see details.source).
-- ============================================================================

do $$
declare
  me uuid;
begin
  select id into me from auth.users where email = 'vinces.gerardo@gmail.com';
  if me is null then raise exception 'No auth user for that email.'; end if;

  insert into public.token_assets (owner_id, name, image_url, token_type, size_category, creature_type, details)
  select me, v.name, v.image_url, 'monster', v.size, v.ctype,
         jsonb_build_object('kind','monster','monster', v.mb::jsonb)
  from (values
    ('Flying Sword', '/icons/monsters/_mono/F.svg', 'small', 'construct', '{"name":"Flying Sword","size":"small","type":"construct","ac":17,"hp":17,"speed":{"walk":0,"fly":50,"hover":true},"abilities":{"str":12,"dex":15,"con":11,"int":1,"wis":5,"cha":1},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"5d6","saves":{"dex":4},"damageImmunities":["Poison","Psychic"],"conditionImmunities":["Blinded","Charmed","Deafened","Frightened","Paralyzed","Petrified","Poisoned"],"senses":["Blindsight 60 ft.","Passive Perception 7"],"languages":["--"],"traits":[{"name":"Antimagic Susceptibility","text":"The sword is incapacitated while in the area of an antimagic field. If targeted by dispel magic, the sword must succeed on a Constitution saving throw against the caster''s spell save DC or fall unconscious for 1 minute."},{"name":"False Appearance","text":"While the sword remains motionless and isn''t flying, it is indistinguishable from a normal sword."}],"actions":[{"name":"Longsword","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 5 (1d8 + 1) slashing damage.","attackBonus":3,"reach":"5 ft","damage":"1d8+1","damageType":"slashing"}]}'),
    ('Frog', '/icons/monsters/_mono/F.svg', 'tiny', 'beast', '{"name":"Frog","size":"tiny","type":"beast","ac":11,"hp":1,"speed":{"walk":20,"swim":20},"abilities":{"str":1,"dex":13,"con":8,"int":1,"wis":8,"cha":3},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4 - 1","skills":[{"name":"Perception","bonus":1},{"name":"Stealth","bonus":3}],"senses":["Darkvision 30 ft.","Passive Perception 11"],"languages":["--"],"traits":[{"name":"Amphibious","text":"The frog can breathe air and water."},{"name":"Standing Leap","text":"The frog''s long jump is up to 10 feet and its high jump is up to 5 feet, with or without a running start."}]}'),
    ('Frost Giant', '/icons/monsters/_mono/F.svg', 'huge', 'giant', '{"name":"Frost Giant","size":"huge","type":"giant","ac":15,"hp":138,"speed":{"walk":40},"abilities":{"str":23,"dex":9,"con":21,"int":9,"wis":10,"cha":12},"cr":"8","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Patchwork Armor","hitDice":"12d12 + 60","saves":{"con":8,"wis":3,"cha":4},"skills":[{"name":"Athletics","bonus":9},{"name":"Perception","bonus":3}],"damageImmunities":["Cold"],"senses":["Passive Perception 13"],"languages":["Giant"],"actions":[{"name":"Multiattack","text":"The giant makes two greataxe attacks."},{"name":"Greataxe","text":"Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 25 (3d12 + 6) slashing damage.","attackBonus":9,"reach":"10 ft","damage":"3d12+6","damageType":"slashing"},{"name":"Rock","text":"Ranged Weapon Attack: +9 to hit, range 60/240 ft., one target. Hit: 28 (4d10 + 6) bludgeoning damage.","attackBonus":9,"reach":"range 60/240 ft","damage":"4d10+6","damageType":"bludgeoning"}]}'),
    ('Gargoyle', '/icons/monsters/_mono/G.svg', 'medium', 'elemental', '{"name":"Gargoyle","size":"medium","type":"elemental","ac":15,"hp":52,"speed":{"walk":30,"fly":60},"abilities":{"str":15,"dex":11,"con":16,"int":6,"wis":11,"cha":7},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"7d8 + 21","damageResistances":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Adamantine"],"damageImmunities":["Poison"],"conditionImmunities":["Exhaustion","Petrified","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Terran"],"traits":[{"name":"False Appearance","text":"While the gargoyle remains motionless, it is indistinguishable from an inanimate statue."}],"actions":[{"name":"Multiattack","text":"The gargoyle makes two attacks: one with its bite and one with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) slashing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"slashing"}]}'),
    ('Gelatinous Cube', '/icons/monsters/_mono/G.svg', 'large', 'ooze', '{"name":"Gelatinous Cube","size":"large","type":"ooze","ac":6,"hp":84,"speed":{"walk":15},"abilities":{"str":14,"dex":3,"con":20,"int":1,"wis":6,"cha":1},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"8d10 + 40","conditionImmunities":["Blinded","Charmed","Deafened","Exhaustion","Frightened","Prone"],"senses":["Blindsight 60 ft.","Passive Perception 8"],"languages":["--"],"traits":[{"name":"Ooze Cube","text":"The cube takes up its entire space. Other creatures can enter the space, but a creature that does so is subjected to the cube''s Engulf and has disadvantage on the saving throw."},{"name":"Transparent","text":"Even when the cube is in plain sight, it takes a successful DC 15 Wisdom (Perception) check to spot a cube that has neither moved nor attacked. A creature that tries to enter the cube''s space while unaware of the cube is surprised by the cube."}],"actions":[{"name":"Pseudopod","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 10 (3d6) acid damage.","attackBonus":4,"reach":"5 ft","damage":"3d6","damageType":"acid"},{"name":"Engulf","text":"The cube moves up to its speed. While doing so, it can enter Large or smaller creatures'' spaces. Whenever the cube enters a creature''s space, the creature must make a DC 12 Dexterity saving throw.","saveDc":12,"saveAbility":"dex"}]}'),
    ('Ghast', '/icons/monsters/_mono/G.svg', 'medium', 'undead', '{"name":"Ghast","size":"medium","type":"undead","ac":13,"hp":36,"speed":{"walk":30},"abilities":{"str":16,"dex":17,"con":10,"int":11,"wis":10,"cha":8},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","hitDice":"8d8","damageResistances":["Necrotic"],"damageImmunities":["Poison"],"conditionImmunities":["Charmed","Exhaustion","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Common"],"traits":[{"name":"Stench","text":"Any creature that starts its turn within 5 feet of the ghast must succeed on a DC 10 Constitution saving throw or be poisoned until the start of its next turn. On a successful saving throw, the creature is immune to the ghast''s Stench for 24 hours."},{"name":"Turning Defiance","text":"The ghast and any ghouls within 30 feet of it have advantage on saving throws against effects that turn undead."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 12 (2d8 + 3) piercing damage.","attackBonus":3,"reach":"5 ft","damage":"2d8+3","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage. If the target is a creature other than an undead, it must succeed on a DC 10 Constitution saving throw or be paralyzed for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"slashing","saveDc":10,"saveAbility":"con"}]}'),
    ('Ghost', '/icons/monsters/_mono/G.svg', 'medium', 'undead', '{"name":"Ghost","size":"medium","type":"undead","ac":11,"hp":45,"speed":{"walk":0,"fly":40,"hover":true},"abilities":{"str":7,"dex":13,"con":10,"int":10,"wis":12,"cha":17},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","hitDice":"10d8","damageResistances":["Acid","Fire","Lightning","Thunder","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Cold","Necrotic","Poison"],"conditionImmunities":["Charmed","Exhaustion","Frightened","Grappled","Paralyzed","Petrified","Poisoned","Prone","Restrained"],"senses":["Darkvision 60 ft.","Passive Perception 11"],"languages":["Any languages it knew in life"],"traits":[{"name":"Ethereal Sight","text":"The ghost can see 60 feet into the Ethereal Plane when it is on the Material Plane, and vice versa."},{"name":"Incorporeal Movement","text":"The ghost can move through other creatures and objects as if they were difficult terrain. It takes 5 (1d10) force damage if it ends its turn inside an object."}],"actions":[{"name":"Withering Touch","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 17 (4d6 + 3) necrotic damage.","attackBonus":5,"reach":"5 ft","damage":"4d6+3","damageType":"necrotic"},{"name":"Etherealness","text":"The ghost enters the Ethereal Plane from the Material Plane, or vice versa. It is visible on the Material Plane while it is in the Border Ethereal, and vice versa, yet it can''t affect or be affected by anything on the other plane."},{"name":"Horrifying Visage","text":"Each non-undead creature within 60 feet of the ghost that can see it must succeed on a DC 13 Wisdom saving throw or be frightened for 1 minute. If the save fails by 5 or more, the target also ages 1d4 × 10 years. A frightened target can repeat the saving throw at the end of each of its turns, ending the frightened condition on itself on a success. If a target''s saving throw is successful or the effect ends for it, the target is immune to this ghost''s Horrifying Visage for the next 24 hours. The aging effect can be reversed with a greater restoration spell, but only within 24 hours of it occurring.","saveDc":13,"saveAbility":"wis"},{"name":"Possession (Recharge 6)","text":"One humanoid that the ghost can see within 5 feet of it must succeed on a DC 13 Charisma saving throw or be possessed by the ghost; the ghost then disappears, and the target is incapacitated and loses control of its body. The ghost now controls the body but doesn''t deprive the target of awareness. The ghost can''t be targeted by any attack, spell, or other effect, except ones that turn undead, and it retains its alignment, Intelligence, Wisdom, Charisma, and immunity to being charmed and frightened. It otherwise uses the possessed target''s statistics, but doesn''t gain access to the target''s knowledge, class features, or proficiencies.","saveDc":13,"saveAbility":"cha"}]}'),
    ('Ghoul', '/icons/monsters/_mono/G.svg', 'medium', 'undead', '{"name":"Ghoul","size":"medium","type":"undead","ac":12,"hp":22,"speed":{"walk":30},"abilities":{"str":13,"dex":15,"con":10,"int":7,"wis":10,"cha":6},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","hitDice":"5d8","damageImmunities":["Poison"],"conditionImmunities":["Charmed","Exhaustion","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Common"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one creature. Hit: 9 (2d6 + 2) piercing damage.","attackBonus":2,"reach":"5 ft","damage":"2d6+2","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (2d4 + 2) slashing damage. If the target is a creature other than an elf or undead, it must succeed on a DC 10 Constitution saving throw or be paralyzed for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attackBonus":4,"reach":"5 ft","damage":"2d4+2","damageType":"slashing","saveDc":10,"saveAbility":"con"}]}'),
    ('Giant Ape', '/icons/monsters/_mono/G.svg', 'huge', 'beast', '{"name":"Giant Ape","size":"huge","type":"beast","ac":12,"hp":157,"speed":{"walk":40,"climb":40},"abilities":{"str":23,"dex":14,"con":18,"int":7,"wis":12,"cha":7},"cr":"7","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"15d12 + 60","skills":[{"name":"Athletics","bonus":9},{"name":"Perception","bonus":4}],"senses":["Passive Perception 14"],"languages":["--"],"actions":[{"name":"Multiattack","text":"The ape makes two fist attacks."},{"name":"Fist","text":"Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 22 (3d10 + 6) bludgeoning damage.","attackBonus":9,"reach":"10 ft","damage":"3d10+6","damageType":"bludgeoning"},{"name":"Rock","text":"Ranged Weapon Attack: +9 to hit, range 50/100 ft., one target. Hit: 30 (7d6 + 6) bludgeoning damage.","attackBonus":9,"reach":"range 50/100 ft","damage":"7d6+6","damageType":"bludgeoning"}]}'),
    ('Giant Badger', '/icons/monsters/_mono/G.svg', 'medium', 'beast', '{"name":"Giant Badger","size":"medium","type":"beast","ac":10,"hp":13,"speed":{"walk":30,"burrow":10},"abilities":{"str":13,"dex":10,"con":15,"int":2,"wis":12,"cha":5},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d8 + 4","senses":["Darkvision 30 ft.","Passive Perception 11"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The badger has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Multiattack","text":"The badger makes two attacks: one with its bite and one with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) piercing damage.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 6 (2d4 + 1) slashing damage.","attackBonus":3,"reach":"5 ft","damage":"2d4+1","damageType":"slashing"}]}'),
    ('Giant Bat', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Bat","size":"large","type":"beast","ac":13,"hp":22,"speed":{"walk":10,"fly":60},"abilities":{"str":15,"dex":16,"con":11,"int":2,"wis":12,"cha":6},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"4d10","senses":["Blindsight 60 ft.","Passive Perception 11"],"languages":["--"],"traits":[{"name":"Echolocation","text":"The bat can''t use its blindsight while deafened."},{"name":"Keen Hearing","text":"The bat has advantage on Wisdom (Perception) checks that rely on hearing."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"}]}'),
    ('Giant Boar', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Boar","size":"large","type":"beast","ac":12,"hp":42,"speed":{"walk":40},"abilities":{"str":17,"dex":10,"con":16,"int":2,"wis":7,"cha":5},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"5d10 + 15","senses":["Passive Perception 8"],"languages":["--"],"traits":[{"name":"Charge","text":"If the boar moves at least 20 feet straight toward a target and then hits it with a tusk attack on the same turn, the target takes an extra 7 (2d6) slashing damage. If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone."},{"name":"Relentless (Recharges after a Short or Long Rest)","text":"If the boar takes 10 damage or less that would reduce it to 0 hit points, it is reduced to 1 hit point instead."}],"actions":[{"name":"Tusk","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"slashing"}]}'),
    ('Giant Centipede', '/icons/monsters/_mono/G.svg', 'small', 'beast', '{"name":"Giant Centipede","size":"small","type":"beast","ac":13,"hp":4,"speed":{"walk":30,"climb":30},"abilities":{"str":5,"dex":14,"con":12,"int":1,"wis":7,"cha":3},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"1d6 + 1","senses":["Blindsight 30 ft.","Passive Perception 8"],"languages":["--"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 4 (1d4 + 2) piercing damage, and the target must succeed on a DC 11 Constitution saving throw or take 10 (3d6) poison damage. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"piercing","saveDc":11,"saveAbility":"con"}]}'),
    ('Giant Constrictor Snake', '/icons/monsters/_mono/G.svg', 'huge', 'beast', '{"name":"Giant Constrictor Snake","size":"huge","type":"beast","ac":12,"hp":60,"speed":{"walk":30,"swim":30},"abilities":{"str":19,"dex":14,"con":12,"int":1,"wis":10,"cha":3},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"8d12 + 8","skills":[{"name":"Perception","bonus":2}],"senses":["Blindsight 10 ft.","Passive Perception 12"],"languages":["--"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 10 ft., one creature. Hit: 11 (2d6 + 4) piercing damage.","attackBonus":6,"reach":"10 ft","damage":"2d6+4","damageType":"piercing"},{"name":"Constrict","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one creature. Hit: 13 (2d8 + 4) bludgeoning damage, and the target is grappled (escape DC 16). Until this grapple ends, the creature is restrained, and the snake can''t constrict another target.","attackBonus":6,"reach":"5 ft","damage":"2d8+4","damageType":"bludgeoning"}]}'),
    ('Giant Crab', '/icons/monsters/_mono/G.svg', 'medium', 'beast', '{"name":"Giant Crab","size":"medium","type":"beast","ac":15,"hp":13,"speed":{"walk":30,"swim":30},"abilities":{"str":13,"dex":15,"con":11,"int":1,"wis":9,"cha":3},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"3d8","skills":[{"name":"Stealth","bonus":4}],"senses":["Blindsight 30 ft.","Passive Perception 9"],"languages":["--"],"traits":[{"name":"Amphibious","text":"The crab can breathe air and water."}],"actions":[{"name":"Claw","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) bludgeoning damage, and the target is grappled (escape DC 11). The crab has two claws, each of which can grapple only one target.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"bludgeoning"}]}'),
    ('Giant Crocodile', '/icons/monsters/_mono/G.svg', 'huge', 'beast', '{"name":"Giant Crocodile","size":"huge","type":"beast","ac":14,"hp":85,"speed":{"walk":30,"swim":50},"abilities":{"str":21,"dex":9,"con":17,"int":2,"wis":10,"cha":7},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"9d12 + 27","skills":[{"name":"Stealth","bonus":5}],"senses":["Passive Perception 10"],"languages":["--"],"traits":[{"name":"Hold Breath","text":"The crocodile can hold its breath for 30 minutes."}],"actions":[{"name":"Multiattack","text":"The crocodile makes two attacks: one with its bite and one with its tail."},{"name":"Bite","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 21 (3d10 + 5) piercing damage, and the target is grappled (escape DC 16). Until this grapple ends, the target is restrained, and the crocodile can''t bite another target.","attackBonus":8,"reach":"5 ft","damage":"3d10+5","damageType":"piercing"},{"name":"Tail","text":"Melee Weapon Attack: +8 to hit, reach 10 ft., one target not grappled by the crocodile. Hit: 14 (2d8 + 5) bludgeoning damage. If the target is a creature, it must succeed on a DC 16 Strength saving throw or be knocked prone.","attackBonus":8,"reach":"10 ft","damage":"2d8+5","damageType":"bludgeoning","saveDc":16,"saveAbility":"str"}]}'),
    ('Giant Eagle', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Eagle","size":"large","type":"beast","ac":13,"hp":26,"speed":{"walk":10,"fly":80},"abilities":{"str":16,"dex":17,"con":13,"int":8,"wis":14,"cha":10},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral good","hitDice":"4d10 + 4","skills":[{"name":"Perception","bonus":4}],"senses":["Passive Perception 14"],"languages":["Giant Eagle  understands Common and Auran but can''t speak them"],"traits":[{"name":"Keen Sight","text":"The eagle has advantage on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Multiattack","text":"The eagle makes two attacks: one with its beak and one with its talons."},{"name":"Beak","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"piercing"},{"name":"Talons","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"slashing"}]}'),
    ('Giant Elk', '/icons/monsters/_mono/G.svg', 'huge', 'beast', '{"name":"Giant Elk","size":"huge","type":"beast","ac":14,"hp":42,"speed":{"walk":60},"abilities":{"str":19,"dex":16,"con":14,"int":7,"wis":14,"cha":10},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"5d12 + 10","skills":[{"name":"Perception","bonus":4}],"senses":["Passive Perception 14"],"languages":["Elvish","Giant Elk  and Sylvan but can''t speak them"],"traits":[{"name":"Charge","text":"If the elk moves at least 20 feet straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 7 (2d6) damage. If the target is a creature, it must succeed on a DC 14 Strength saving throw or be knocked prone."}],"actions":[{"name":"Ram","text":"Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.","attackBonus":6,"reach":"10 ft","damage":"2d6+4","damageType":"bludgeoning"},{"name":"Hooves","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one prone creature. Hit: 22 (4d8 + 4) bludgeoning damage.","attackBonus":6,"reach":"5 ft","damage":"4d8+4","damageType":"bludgeoning"}]}'),
    ('Giant Fire Beetle', '/icons/monsters/_mono/G.svg', 'small', 'beast', '{"name":"Giant Fire Beetle","size":"small","type":"beast","ac":13,"hp":4,"speed":{"walk":30},"abilities":{"str":8,"dex":10,"con":12,"int":1,"wis":7,"cha":3},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"1d6 + 1","senses":["Blindsight 30 ft.","Passive Perception 8"],"languages":["--"],"traits":[{"name":"Illumination","text":"The beetle sheds bright light in a 10-foot radius and dim light for an additional 10 feet."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +1 to hit, reach 5 ft., one target. Hit: 2 (1d6 − 1) slashing damage.","attackBonus":1,"reach":"5 ft"}]}'),
    ('Giant Frog', '/icons/monsters/_mono/G.svg', 'medium', 'beast', '{"name":"Giant Frog","size":"medium","type":"beast","ac":11,"hp":18,"speed":{"walk":30,"swim":30},"abilities":{"str":12,"dex":13,"con":11,"int":2,"wis":10,"cha":3},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"4d8","skills":[{"name":"Perception","bonus":2},{"name":"Stealth","bonus":3}],"senses":["Darkvision 30 ft.","Passive Perception 12"],"languages":["--"],"traits":[{"name":"Amphibious","text":"The frog can breathe air and water."},{"name":"Standing Leap","text":"The frog''s long jump is up to 20 feet and its high jump is up to 10 feet, with or without a running start."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) piercing damage, and the target is grappled (escape DC 11). Until this grapple ends, the target is restrained, and the frog can''t bite another target.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"piercing"},{"name":"Swallow","text":"The frog makes one bite attack against a Small or smaller target it is grappling. If the attack hits, the target is swallowed, and the grapple ends. The swallowed target is blinded and restrained, it has total cover against attacks and other effects outside the frog, and it takes 5 (2d4) acid damage at the start of each of the frog''s turns. The frog can have only one target swallowed at a time. If the frog dies, a swallowed creature is no longer restrained by it and can escape from the corpse using 5 feet of movement, exiting prone."}]}'),
    ('Giant Goat', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Goat","size":"large","type":"beast","ac":11,"hp":19,"speed":{"walk":40},"abilities":{"str":17,"dex":11,"con":12,"int":3,"wis":12,"cha":6},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"3d10 + 3","senses":["Passive Perception 11"],"languages":["--"],"traits":[{"name":"Charge","text":"If the goat moves at least 20 feet straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 5 (2d4) bludgeoning damage. If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone."},{"name":"Sure-Footed","text":"The goat has advantage on Strength and Dexterity saving throws made against effects that would knock it prone."}],"actions":[{"name":"Ram","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (2d4 + 3) bludgeoning damage.","attackBonus":5,"reach":"5 ft","damage":"2d4+3","damageType":"bludgeoning"}]}'),
    ('Giant Hyena', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Hyena","size":"large","type":"beast","ac":12,"hp":45,"speed":{"walk":50},"abilities":{"str":16,"dex":14,"con":14,"int":2,"wis":12,"cha":7},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"6d10 + 12","skills":[{"name":"Perception","bonus":3}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Rampage","text":"When the hyena reduces a creature to 0 hit points with a melee attack on its turn, the hyena can take a bonus action to move up to half its speed and make a bite attack."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"piercing"}]}'),
    ('Giant Lizard', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Lizard","size":"large","type":"beast","ac":12,"hp":19,"speed":{"walk":30,"climb":30},"abilities":{"str":15,"dex":12,"con":13,"int":2,"wis":10,"cha":5},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"3d10 + 3","senses":["Darkvision 30 ft.","Passive Perception 10"],"languages":["--"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d8+2","damageType":"piercing"}]}'),
    ('Giant Octopus', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Octopus","size":"large","type":"beast","ac":11,"hp":52,"speed":{"walk":10,"swim":60},"abilities":{"str":17,"dex":13,"con":13,"int":4,"wis":10,"cha":4},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"8d10 + 8","skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":5}],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["--"],"traits":[{"name":"Hold Breath","text":"While out of water, the octopus can hold its breath for 1 hour."},{"name":"Underwater Camouflage","text":"The octopus has advantage on Dexterity (Stealth) checks made while underwater."},{"name":"Water Breathing","text":"The octopus can breathe only underwater."}],"actions":[{"name":"Tentacles","text":"Melee Weapon Attack: +5 to hit, reach 15 ft., one target. Hit: 10 (2d6 + 3) bludgeoning damage. If the target is a creature, it is grappled (escape DC 16). Until this grapple ends, the target is restrained, and the octopus can''t use its tentacles on another target.","attackBonus":5,"reach":"15 ft","damage":"2d6+3","damageType":"bludgeoning"},{"name":"Ink Cloud (Recharges after a Short or Long Rest)","text":"A 20- foot-radius cloud of ink extends all around the octopus if it is underwater. The area is heavily obscured for 1 minute, although a significant current can disperse the ink. After releasing the ink, the octopus can use the Dash action as a bonus action."}]}'),
    ('Giant Owl', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Owl","size":"large","type":"beast","ac":12,"hp":19,"speed":{"walk":5,"fly":60},"abilities":{"str":13,"dex":15,"con":12,"int":8,"wis":13,"cha":10},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","hitDice":"3d10 + 3","skills":[{"name":"Perception","bonus":5},{"name":"Stealth","bonus":4}],"senses":["Darkvision 120 ft.","Passive Perception 15"],"languages":["Elvish","Giant Owl  and Sylvan but can''t speak them"],"traits":[{"name":"Flyby","text":"The owl doesn''t provoke opportunity attacks when it flies out of an enemy''s reach."},{"name":"Keen Hearing and Sight","text":"The owl has advantage on Wisdom (Perception) checks that rely on hearing or sight."}],"actions":[{"name":"Talons","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 8 (2d6 + 1) slashing damage.","attackBonus":3,"reach":"5 ft","damage":"2d6+1","damageType":"slashing"}]}'),
    ('Giant Poisonous Snake', '/icons/monsters/_mono/G.svg', 'medium', 'beast', '{"name":"Giant Poisonous Snake","size":"medium","type":"beast","ac":14,"hp":11,"speed":{"walk":30,"swim":30},"abilities":{"str":10,"dex":18,"con":13,"int":2,"wis":10,"cha":3},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d8 + 2","skills":[{"name":"Perception","bonus":2}],"senses":["Blindsight 10 ft.","Passive Perception 12"],"languages":["--"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 6 (1d4 + 4) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 10 (3d6) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":6,"reach":"10 ft","damage":"1d4+4","damageType":"piercing","saveDc":11,"saveAbility":"con"}]}'),
    ('Giant Rat', '/icons/monsters/_mono/G.svg', 'small', 'beast', '{"name":"Giant Rat","size":"small","type":"beast","ac":12,"hp":7,"speed":{"walk":30},"abilities":{"str":7,"dex":15,"con":11,"int":2,"wis":10,"cha":4},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d6","senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The rat has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Pack Tactics","text":"The rat has advantage on an attack roll against a creature if at least one of the rat''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"piercing"}]}'),
    ('Giant Scorpion', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Scorpion","size":"large","type":"beast","ac":15,"hp":52,"speed":{"walk":40},"abilities":{"str":15,"dex":13,"con":15,"int":1,"wis":9,"cha":3},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"7d10 + 14","senses":["Blindsight 60 ft.","Passive Perception 9"],"languages":["--"],"actions":[{"name":"Multiattack","text":"The scorpion makes three attacks: two with its claws and one with its sting."},{"name":"Claw","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) bludgeoning damage, and the target is grappled (escape DC 12). The scorpion has two claws, each of which can grapple only one target.","attackBonus":4,"reach":"5 ft","damage":"1d8+2","damageType":"bludgeoning"},{"name":"Sting","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 7 (1d10 + 2) piercing damage, and the target must make a DC 12 Constitution saving throw, taking 22 (4d10) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":4,"reach":"5 ft","damage":"1d10+2","damageType":"piercing","saveDc":12,"saveAbility":"con"}]}'),
    ('Giant Sea Horse', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Sea Horse","size":"large","type":"beast","ac":13,"hp":16,"speed":{"walk":0,"swim":40},"abilities":{"str":12,"dex":15,"con":11,"int":2,"wis":12,"cha":5},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"3d10","senses":["Passive Perception 11"],"languages":["--"],"traits":[{"name":"Charge","text":"If the sea horse moves at least 20 feet straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 7 (2d6) bludgeoning damage. It the target is a creature, it must succeed on a DC 11 Strength saving throw or be knocked prone."},{"name":"Water Breathing","text":"The sea horse can breathe only underwater."}],"actions":[{"name":"Ram","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) bludgeoning damage.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"bludgeoning"}]}'),
    ('Giant Shark', '/icons/monsters/_mono/G.svg', 'huge', 'beast', '{"name":"Giant Shark","size":"huge","type":"beast","ac":13,"hp":126,"speed":{"walk":0,"swim":50},"abilities":{"str":23,"dex":11,"con":21,"int":1,"wis":10,"cha":5},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"11d12 + 55","skills":[{"name":"Perception","bonus":3}],"senses":["Blindsight 60 ft.","Passive Perception 13"],"languages":["--"],"traits":[{"name":"Blood Frenzy","text":"The shark has advantage on melee attack rolls against any creature that doesn''t have all its hit points."},{"name":"Water Breathing","text":"The shark can breathe only underwater."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 22 (3d10 + 6) piercing damage.","attackBonus":9,"reach":"5 ft","damage":"3d10+6","damageType":"piercing"}]}'),
    ('Giant Spider', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Spider","size":"large","type":"beast","ac":14,"hp":26,"speed":{"walk":30,"climb":30},"abilities":{"str":14,"dex":16,"con":12,"int":2,"wis":11,"cha":4},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"4d10 + 4","skills":[{"name":"Stealth","bonus":7}],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Spider Climb","text":"The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Web Sense","text":"While in contact with a web, the spider knows the exact location of any other creature in contact with the same web."},{"name":"Web Walker","text":"The spider ignores movement restrictions caused by webbing."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 7 (1d8 + 3) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 9 (2d8) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","attackBonus":5,"reach":"5 ft","damage":"1d8+3","damageType":"piercing","saveDc":11,"saveAbility":"con"},{"name":"Web (Recharge 5–6)","text":"Ranged Weapon Attack: +5 to hit, range 30/60 ft., one creature. Hit: The target is restrained by webbing. As an action, the restrained target can make a DC 12 Strength check, bursting the webbing on a success. The webbing can also be attacked and destroyed (AC 10; hp 5; vulnerability to fire damage; immunity to bludgeoning, poison, and psychic damage).","attackBonus":5,"reach":"range 30/60 ft"}]}'),
    ('Giant Toad', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Toad","size":"large","type":"beast","ac":11,"hp":39,"speed":{"walk":20,"swim":40},"abilities":{"str":15,"dex":13,"con":13,"int":2,"wis":10,"cha":3},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"6d10 + 6","senses":["Darkvision 30 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Amphibious","text":"The toad can breathe air and water."},{"name":"Standing Leap","text":"The toad''s long jump is up to 20 feet and its high jump is up to 10 feet, with or without a running start."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage plus 5 (1d10) poison damage, and the target is grappled (escape DC 13). Until this grapple ends, the target is restrained, and the toad can''t bite another target.","attackBonus":4,"reach":"5 ft","damage":"1d10+2","damageType":"piercing"},{"name":"Swallow","text":"The toad makes one bite attack against a Medium or smaller target it is grappling. If the attack hits, the target is swallowed, and the grapple ends. The swallowed target is blinded and restrained, it has total cover against attacks and other effects outside the toad, and it takes 10 (3d6) acid damage at the start of each of the toad''s turns. The toad can have only one target swallowed at a time. If the toad dies, a swallowed creature is no longer restrained by it and can escape from the corpse using 5 feet of movement, exiting prone."}]}'),
    ('Giant Vulture', '/icons/monsters/_mono/G.svg', 'large', 'beast', '{"name":"Giant Vulture","size":"large","type":"beast","ac":10,"hp":22,"speed":{"walk":10,"fly":60},"abilities":{"str":15,"dex":10,"con":15,"int":6,"wis":12,"cha":7},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","hitDice":"3d10 + 6","skills":[{"name":"Perception","bonus":3}],"senses":["Passive Perception 13"],"languages":["Understands Common but can''t speak  it"],"traits":[{"name":"Keen Sight and Smell","text":"The vulture has advantage on Wisdom (Perception) checks that rely on sight or smell."},{"name":"Pack Tactics","text":"The vulture has advantage on an attack roll against a creature if at least one of the vulture''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Multiattack","text":"The vulture makes two attacks: one with its beak and one with its talons."},{"name":"Beak","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (2d4 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"2d4+2","damageType":"piercing"},{"name":"Talons","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 9 (2d6 + 2) slashing damage.","attackBonus":4,"reach":"5 ft","damage":"2d6+2","damageType":"slashing"}]}'),
    ('Giant Wasp', '/icons/monsters/_mono/G.svg', 'medium', 'beast', '{"name":"Giant Wasp","size":"medium","type":"beast","ac":12,"hp":13,"speed":{"walk":10,"fly":50},"abilities":{"str":10,"dex":14,"con":10,"int":1,"wis":10,"cha":3},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"3d8","senses":["Passive Perception 10"],"languages":["--"],"actions":[{"name":"Sting","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 5 (1d6 + 2) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 10 (3d6) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing","saveDc":11,"saveAbility":"con"}]}'),
    ('Giant Weasel', '/icons/monsters/_mono/G.svg', 'medium', 'beast', '{"name":"Giant Weasel","size":"medium","type":"beast","ac":13,"hp":9,"speed":{"walk":40},"abilities":{"str":11,"dex":16,"con":10,"int":4,"wis":12,"cha":5},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d8","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":5}],"senses":["Darkvision 60 ft.","Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Hearing and Smell","text":"The weasel has advantage on Wisdom (Perception) checks that rely on hearing or smell."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 5 (1d4 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d4+3","damageType":"piercing"}]}'),
    ('Giant Wolf Spider', '/icons/monsters/_mono/G.svg', 'medium', 'beast', '{"name":"Giant Wolf Spider","size":"medium","type":"beast","ac":13,"hp":11,"speed":{"walk":40,"climb":40},"abilities":{"str":12,"dex":16,"con":13,"int":3,"wis":12,"cha":4},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d8 + 2","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":7}],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 13"],"languages":["--"],"traits":[{"name":"Spider Climb","text":"The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Web Sense","text":"While in contact with a web, the spider knows the exact location of any other creature in contact with the same web."},{"name":"Web Walker","text":"The spider ignores movement restrictions caused by webbing."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 4 (1d6 + 1) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 7 (2d6) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"piercing","saveDc":11,"saveAbility":"con"}]}'),
    ('Gibbering Mouther', '/icons/monsters/_mono/G.svg', 'medium', 'aberration', '{"name":"Gibbering Mouther","size":"medium","type":"aberration","ac":9,"hp":67,"speed":{"walk":10,"swim":10},"abilities":{"str":10,"dex":8,"con":16,"int":3,"wis":10,"cha":6},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","hitDice":"9d8 + 27","conditionImmunities":["Prone"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["--"],"traits":[{"name":"Aberrant Ground","text":"The ground in a 10-foot radius around the mouther is doughlike difficult terrain. Each creature that starts its turn in that area must succeed on a DC 10 Strength saving throw or have its speed reduced to 0 until the start of its next turn."},{"name":"Gibbering","text":"The mouther babbles incoherently while it can see any creature and isn''t incapacitated. Each creature that starts its turn within 20 feet of the mouther and can hear the gibbering must succeed on a DC 10 Wisdom saving throw. On a failure, the creature can''t take reactions until the start of its next turn and rolls a d8 to determine what it does during its turn. On a 1 to 4, the creature does nothing. On a 5 or 6, the creature takes no action or bonus action and uses all its movement to move in a randomly determined direction. On a 7 or 8, the creature makes a melee attack against a randomly determined creature within its reach or does nothing if it can''t make such an attack."}],"actions":[{"name":"Multiattack","text":"The gibbering mouther makes one bite attack and, if it can, uses its Blinding Spittle."},{"name":"Bite","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one creature. Hit: 17 (5d6) piercing damage. If the target is Medium or smaller, it must succeed on a DC 10 Strength saving throw or be knocked prone. If the target is killed by this damage, it is absorbed into the mouther.","attackBonus":2,"reach":"5 ft","damage":"5d6","damageType":"piercing","saveDc":10,"saveAbility":"str"},{"name":"Blinding Spittle (Recharge 5–6)","text":"The mouther spits a chemical glob at a point it can see within 15 feet of it. The glob explodes in a blinding flash of light on impact. Each creature within 5 feet of the flash must succeed on a DC 13 Dexterity saving throw or be blinded until the end of the mouther''s next turn.","saveDc":13,"saveAbility":"dex"}]}'),
    ('Glabrezu', '/icons/monsters/_mono/G.svg', 'large', 'fiend', '{"name":"Glabrezu","size":"large","type":"fiend","ac":17,"hp":157,"speed":{"walk":40},"abilities":{"str":20,"dex":15,"con":21,"int":19,"wis":17,"cha":16},"cr":"9","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"15d10 + 75","saves":{"str":9,"con":9,"wis":7,"cha":7},"damageResistances":["Cold","Fire","Lightning","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":["Truesight 120 ft.","Passive Perception 13"],"languages":["Abyssal","Telepathy 120 ft."],"traits":[{"name":"Innate Spellcasting","text":"The glabrezu''s spellcasting ability is Intelligence (spell save DC 16). The glabrezu can innately cast the following spells, requiring no material components:"},{"name":"Magic Resistance","text":"The glabrezu has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The glabrezu makes four attacks: two with its pincers and two with its fists. Alternatively, it makes two attacks with its pincers and casts one spell."},{"name":"Pincer","text":"Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 16 (2d10 + 5) bludgeoning damage. If the target is a Medium or smaller creature, it is grappled (escape DC 15). The glabrezu has two pincers, each of which can grapple only one target.","attackBonus":9,"reach":"10 ft","damage":"2d10+5","damageType":"bludgeoning"},{"name":"Fist","text":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 7 (2d4 + 2) bludgeoning damage.","attackBonus":9,"reach":"5 ft","damage":"2d4+2","damageType":"bludgeoning"}]}'),
    ('Gladiator', '/icons/monsters/_mono/G.svg', 'medium', 'humanoid', '{"name":"Gladiator","size":"medium","type":"humanoid","ac":16,"hp":112,"speed":{"walk":30},"abilities":{"str":18,"dex":15,"con":16,"int":10,"wis":12,"cha":15},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Studded Leather, Shield","hitDice":"15d8 + 45","saves":{"str":7,"dex":5,"con":6},"skills":[{"name":"Athletics","bonus":10},{"name":"Intimidation","bonus":5}],"senses":["Passive Perception 11"],"languages":["Any one language (usually Common)"],"traits":[{"name":"Brave","text":"The gladiator has advantage on saving throws against being frightened."},{"name":"Brute","text":"A melee weapon deals one extra die of its damage when the gladiator hits with it (included in the attack)."}],"actions":[{"name":"Multiattack","text":"The gladiator makes three melee attacks or two ranged attacks."},{"name":"Spear","text":"Melee or Ranged Weapon Attack: +7 to hit, reach 5 ft. and range 20/60 ft., one target. Hit: 11 (2d6 + 4) piercing damage, or 13 (2d8 + 4) piercing damage if used with two hands to make a melee attack.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"piercing"},{"name":"Shield Bash","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one creature. Hit: 9 (2d4 + 4) bludgeoning damage. If the target is a Medium or smaller creature, it must succeed on a DC 15 Strength saving throw or be knocked prone.","attackBonus":7,"reach":"5 ft","damage":"2d4+4","damageType":"bludgeoning","saveDc":15,"saveAbility":"str"}],"reactions":[{"name":"Parry","text":"The gladiator adds 3 to its AC against one melee attack that would hit it. To do so, the gladiator must see the attacker and be wielding a melee weapon."}]}'),
    ('Gnoll', '/icons/monsters/_mono/G.svg', 'medium', 'humanoid', '{"name":"Gnoll","size":"medium","type":"humanoid","ac":15,"hp":22,"speed":{"walk":30},"abilities":{"str":14,"dex":12,"con":11,"int":6,"wis":10,"cha":7},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Hide Armor, Shield","hitDice":"5d8","senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Gnoll"],"traits":[{"name":"Rampage","text":"When the gnoll reduces a creature to 0 hit points with a melee attack on its turn, the gnoll can take a bonus action to move up to half its speed and make a bite attack."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 4 (1d4 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"piercing"},{"name":"Spear","text":"Melee or Ranged Weapon Attack: +4 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 5 (1d6 + 2) piercing damage, or 6 (1d8 + 2) piercing damage if used with two hands to make a melee attack.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Longbow","text":"Ranged Weapon Attack: +3 to hit, range 150/600 ft., one target. Hit: 5 (1d8 + 1) piercing damage.","attackBonus":3,"reach":"range 150/600 ft","damage":"1d8+1","damageType":"piercing"}]}'),
    ('Goat', '/icons/monsters/_mono/G.svg', 'medium', 'beast', '{"name":"Goat","size":"medium","type":"beast","ac":10,"hp":4,"speed":{"walk":40},"abilities":{"str":12,"dex":10,"con":11,"int":2,"wis":10,"cha":5},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d8","senses":["Passive Perception 10"],"languages":["--"],"traits":[{"name":"Charge","text":"If the goat moves at least 20 feet straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 2 (1d4) bludgeoning damage. If the target is a creature, it must succeed on a DC 10 Strength saving throw or be knocked prone."},{"name":"Sure-Footed","text":"The goat has advantage on Strength and Dexterity saving throws made against effects that would knock it prone."}],"actions":[{"name":"Ram","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 3 (1d4 + 1) bludgeoning damage.","attackBonus":3,"reach":"5 ft","damage":"1d4+1","damageType":"bludgeoning"}]}'),
    ('Goblin', '/icons/monsters/_mono/G.svg', 'small', 'humanoid', '{"name":"Goblin","size":"small","type":"humanoid","ac":15,"hp":7,"speed":{"walk":30},"abilities":{"str":8,"dex":14,"con":10,"int":10,"wis":8,"cha":8},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Leather Armor, Shield","hitDice":"2d6","skills":[{"name":"Stealth","bonus":6}],"senses":["Darkvision 60 ft.","Passive Perception 9"],"languages":["Common","Goblin"],"traits":[{"name":"Nimble Escape","text":"The goblin can take the Disengage or Hide action as a bonus action on each of its turns."}],"actions":[{"name":"Scimitar","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) slashing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"slashing"},{"name":"Shortbow","text":"Ranged Weapon Attack: +4 to hit, range 80/320 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"range 80/320 ft","damage":"1d6+2","damageType":"piercing"}]}'),
    ('Gold Dragon Wyrmling', '/icons/monsters/_mono/G.svg', 'medium', 'dragon', '{"name":"Gold Dragon Wyrmling","size":"medium","type":"dragon","ac":17,"hp":60,"speed":{"walk":30,"fly":60,"swim":30},"abilities":{"str":19,"dex":14,"con":17,"int":14,"wis":11,"cha":16},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","hitDice":"8d8 + 24","saves":{"dex":4,"con":5,"wis":2,"cha":5},"skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":4}],"damageImmunities":["Fire"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 14"],"languages":["Draconic"],"traits":[{"name":"Amphibious","text":"Amphibious: The dragon can breathe air and water."}],"actions":[{"name":"Bite","text":"Bite: Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (1d10 + 4) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"1d10+4","damageType":"piercing"},{"name":"Breath Weapons (Recharge 5–6)","text":"Breath Weapons (Recharge 5–6): The dragon uses one of the following breath weapons."},{"name":"Fire Breath","text":"Fire Breath: The dragon exhales fire in a 15-foot cone. Each creature in that area must make a DC 13 Dexterity saving throw, taking 22 (4d10) fire damage on a failed save, or half as much damage on a successful one.","saveDc":13,"saveAbility":"dex"},{"name":"Weakening Breath","text":"Weakening Breath: The dragon exhales gas in a 15-foot cone. Each creature in that area must succeed on a DC 13 Strength saving throw or have disadvantage on Strength-based attack rolls, Strength checks, and Strength saving throws for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","saveDc":13,"saveAbility":"str"}]}'),
    ('Gorgon', '/icons/monsters/_mono/G.svg', 'large', 'monstrosity', '{"name":"Gorgon","size":"large","type":"monstrosity","ac":19,"hp":114,"speed":{"walk":40},"abilities":{"str":20,"dex":11,"con":18,"int":2,"wis":12,"cha":7},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"12d10 + 48","skills":[{"name":"Perception","bonus":4}],"conditionImmunities":["Petrified"],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["--"],"traits":[{"name":"Trampling Charge","text":"If the gorgon moves at least 20 feet straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a DC 16 Strength saving throw or be knocked prone. If the target is prone, the gorgon can make one attack with its hooves against it as a bonus action."}],"actions":[{"name":"Gore","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 18 (2d12 + 5) piercing damage.","attackBonus":8,"reach":"5 ft","damage":"2d12+5","damageType":"piercing"},{"name":"Hooves","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 16 (2d10 + 5) bludgeoning damage.","attackBonus":8,"reach":"5 ft","damage":"2d10+5","damageType":"bludgeoning"},{"name":"Petrifying Breath (Recharge 5–6)","text":"The gorgon exhales petrifying gas in a 30-foot cone. Each creature in that area must succeed on a DC 13 Constitution saving throw. On a failed save, a target begins to turn to stone and is restrained. The restrained target must repeat the saving throw at the end of its next turn. On a success, the effect ends on the target. On a failure, the target is petrified until freed by the greater restoration spell or other magic.","saveDc":13,"saveAbility":"con"}]}'),
    ('Gray Ooze', '/icons/monsters/_mono/G.svg', 'medium', 'ooze', '{"name":"Gray Ooze","size":"medium","type":"ooze","ac":8,"hp":22,"speed":{"walk":10,"climb":10},"abilities":{"str":12,"dex":6,"con":16,"int":1,"wis":6,"cha":2},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"3d8 + 9","skills":[{"name":"Stealth","bonus":2}],"damageResistances":["Acid","Cold","Fire"],"conditionImmunities":["Blinded","Charmed","Deafened","Exhaustion","Frightened","Prone"],"senses":["Blindsight 60 ft.","Passive Perception 8"],"languages":["--"],"traits":[{"name":"Amorphous","text":"The ooze can move through a space as narrow as 1 inch wide without squeezing."},{"name":"Corrode Metal","text":"Any nonmagical weapon made of metal that hits the ooze corrodes. After dealing damage, the weapon takes a permanent and cumulative −1 penalty to damage rolls. If its penalty drops to −5, the weapon is destroyed. Nonmagical ammunition made of metal that hits the ooze is destroyed after dealing damage."},{"name":"False Appearance","text":"While the ooze remains motionless, it is indistinguishable from an oily pool or wet rock."}],"actions":[{"name":"Pseudopod","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) bludgeoning damage plus 7 (2d6) acid damage, and if the target is wearing nonmagical metal armor, its armor is partly corroded and takes a permanent and cumulative −1 penalty to the AC it offers. The armor is destroyed if the penalty reduces its AC to 10.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"bludgeoning"}]}'),
    ('Green Dragon Wyrmling', '/icons/monsters/_mono/G.svg', 'medium', 'dragon', '{"name":"Green Dragon Wyrmling","size":"medium","type":"dragon","ac":17,"hp":38,"speed":{"walk":30,"fly":60,"swim":30},"abilities":{"str":15,"dex":12,"con":13,"int":14,"wis":11,"cha":13},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"7d8 + 7","saves":{"dex":3,"con":3,"wis":2,"cha":3},"skills":[{"name":"Perception","bonus":4},{"name":"Stealth","bonus":3}],"damageImmunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 14"],"languages":["Draconic"],"traits":[{"name":"Amphibious","text":"The dragon can breathe air and water."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage plus 3 (1d6) poison damage.","attackBonus":4,"reach":"5 ft","damage":"1d10+2","damageType":"piercing"},{"name":"Poison Breath (Recharge 5–6)","text":"The dragon exhales poisonous gas in a 15-foot cone. Each creature in that area must make a DC 11 Constitution saving throw, taking 21 (6d6) poison damage on a failed save, or half as much damage on a successful one.","saveDc":11,"saveAbility":"con"}]}'),
    ('Green Hag', '/icons/monsters/_mono/G.svg', 'medium', 'fey', '{"name":"Green Hag","size":"medium","type":"fey","ac":17,"hp":82,"speed":{"walk":30},"abilities":{"str":18,"dex":12,"con":16,"int":13,"wis":14,"cha":14},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Natural Armor","hitDice":"11d8 + 33","skills":[{"name":"Arcana","bonus":3},{"name":"Deception","bonus":4},{"name":"Perception","bonus":4},{"name":"Stealth","bonus":3}],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["Common","Draconic","Sylvan"],"traits":[{"name":"Amphibious","text":"The hag can breathe air and water."},{"name":"Innate Spellcasting","text":"The hag''s innate spellcasting ability is Charisma (spell save DC 12). She can innately cast the following spells, requiring no material components:"},{"name":"Mimicry","text":"The hag can mimic animal sounds and humanoid voices. A creature that hears the sounds can tell they are imitations with a successful DC 14 Wisdom (Insight) check."}],"actions":[{"name":"Claws","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) slashing damage.","attackBonus":6,"reach":"5 ft","damage":"2d8+4","damageType":"slashing"},{"name":"Illusory Appearance","text":"The hag covers herself and anything she is wearing or carrying with a magical illusion that makes her look like another creature of her general size and humanoid shape. The illusion ends if the hag takes a bonus action to end it or if she dies."},{"name":"Invisible Passage","text":"The hag magically turns invisible until she attacks or casts a spell, or until her concentration ends (as if concentrating on a spell). While invisible, she leaves no physical evidence of her passage, so she can be tracked only by magic. Any equipment she wears or carries is invisible with her."}]}'),
    ('Grick', '/icons/monsters/_mono/G.svg', 'medium', 'monstrosity', '{"name":"Grick","size":"medium","type":"monstrosity","ac":14,"hp":27,"speed":{"walk":30,"climb":30},"abilities":{"str":14,"dex":14,"con":11,"int":3,"wis":14,"cha":5},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"Natural Armor","hitDice":"6d8","damageResistances":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"senses":["Darkvision 60 ft.","Passive Perception 12"],"languages":["--"],"traits":[{"name":"Stone Camouflage","text":"The grick has advantage on Dexterity (Stealth) checks made to hide in rocky terrain."}],"actions":[{"name":"Multiattack","text":"The grick makes one attack with its tentacles. If that attack hits, the grick can make one beak attack against the same target."},{"name":"Tentacles","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 9 (2d6 + 2) slashing damage.","attackBonus":4,"reach":"5 ft","damage":"2d6+2","damageType":"slashing"},{"name":"Beak","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"}]}'),
    ('Griffon', '/icons/monsters/_mono/G.svg', 'large', 'monstrosity', '{"name":"Griffon","size":"large","type":"monstrosity","ac":12,"hp":59,"speed":{"walk":30,"fly":80},"abilities":{"str":18,"dex":15,"con":16,"int":2,"wis":13,"cha":8},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"7d10 + 21","skills":[{"name":"Perception","bonus":5}],"senses":["Darkvision 60 ft.","Passive Perception 15"],"languages":["--"],"traits":[{"name":"Keen Sight","text":"The griffon has advantage on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Multiattack","text":"The griffon makes two attacks: one with its beak and one with its claws."},{"name":"Beak","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 8 (1d8 + 4) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"1d8+4","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) slashing damage.","attackBonus":6,"reach":"5 ft","damage":"2d6+4","damageType":"slashing"}]}'),
    ('Grimlock', '/icons/monsters/_mono/G.svg', 'medium', 'humanoid', '{"name":"Grimlock","size":"medium","type":"humanoid","ac":11,"hp":11,"speed":{"walk":30},"abilities":{"str":16,"dex":12,"con":12,"int":9,"wis":8,"cha":6},"cr":"1/4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"2d8 + 2","skills":[{"name":"Athletics","bonus":5},{"name":"Perception","bonus":3},{"name":"Stealth","bonus":3}],"conditionImmunities":["Blinded"],"senses":["Blindsight 30 ft.","Passive Perception 13"],"languages":["Undercommon"],"traits":[{"name":"Blind Senses","text":"The grimlock can''t use its blindsight while deafened and unable to smell."},{"name":"Keen Hearing and Smell","text":"The grimlock has advantage on Wisdom (Perception) checks that rely on hearing or smell."},{"name":"Stone Camouflage","text":"The grimlock has advantage on Dexterity (Stealth) checks made to hide in rocky terrain."}],"actions":[{"name":"Spiked Bone Club","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 5 (1d4 + 3) bludgeoning damage plus 2 (1d4) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d4+3","damageType":"bludgeoning"}]}'),
    ('Guard', '/icons/monsters/_mono/G.svg', 'medium', 'humanoid', '{"name":"Guard","size":"medium","type":"humanoid","ac":16,"hp":11,"speed":{"walk":30},"abilities":{"str":13,"dex":12,"con":12,"int":10,"wis":11,"cha":10},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Chain Shirt, Shield","hitDice":"2d8 + 2","skills":[{"name":"Perception","bonus":2}],"senses":["Passive Perception 12"],"languages":["Any one language (usually Common)"],"actions":[{"name":"Spear","text":"Melee or Ranged Weapon Attack: +3 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 4 (1d6 + 1) piercing damage, or 5 (1d8 + 1) piercing damage if used with two hands to make a melee attack.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"piercing"}]}'),
    ('Guardian Naga', '/icons/monsters/_mono/G.svg', 'large', 'monstrosity', '{"name":"Guardian Naga","size":"large","type":"monstrosity","ac":18,"hp":127,"speed":{"walk":40},"abilities":{"str":19,"dex":18,"con":16,"int":16,"wis":19,"cha":18},"cr":"10","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful good","acNote":"Natural Armor","hitDice":"15d10 + 45","saves":{"dex":8,"con":7,"int":7,"wis":8,"cha":8},"damageImmunities":["Poison"],"conditionImmunities":["Charmed","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["Celestial","Common"],"traits":[{"name":"Rejuvenation","text":"If it dies, the naga returns to life in 1d6 days and regains all its hit points. Only a wish spell can prevent this trait from functioning."},{"name":"Spellcasting","text":"The naga is an 11th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 16, +8 to hit with spell attacks), and it needs only verbal components to cast its spells. It has the following cleric spells prepared:"}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +8 to hit, reach 10 ft., one creature. Hit: 8 (1d8 + 4) piercing damage, and the target must make a DC 15 Constitution saving throw, taking 45 (10d8) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":8,"reach":"10 ft","damage":"1d8+4","damageType":"piercing","saveDc":15,"saveAbility":"con"},{"name":"Spit Poison","text":"Ranged Weapon Attack: +8 to hit, range 15/30 ft., one creature. Hit: The target must make a DC 15 Constitution saving throw, taking 45 (10d8) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":8,"reach":"range 15/30 ft","damage":"10d8","damageType":"poison","saveDc":15,"saveAbility":"con"}]}'),
    ('Gynosphinx', '/icons/monsters/_mono/G.svg', 'large', 'monstrosity', '{"name":"Gynosphinx","size":"large","type":"monstrosity","ac":17,"hp":136,"speed":{"walk":40,"fly":60},"abilities":{"str":18,"dex":15,"con":16,"int":18,"wis":18,"cha":18},"cr":"11","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful neutral","acNote":"Natural Armor","hitDice":"16d10 + 48","skills":[{"name":"Arcana","bonus":12},{"name":"History","bonus":12},{"name":"Perception","bonus":8},{"name":"Religion","bonus":8}],"damageResistances":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Psychic"],"conditionImmunities":["Charmed","Frightened"],"senses":["Truesight 120 ft.","Passive Perception 18"],"languages":["Common","Sphinx"],"traits":[{"name":"Inscrutable","text":"The sphinx is immune to any effect that would sense its emotions or read its thoughts, as well as any divination spell that it refuses. Wisdom (Insight) checks made to ascertain the sphinx''s intentions or sincerity have disadvantage."},{"name":"Magic Weapons","text":"The sphinx''s weapon attacks are magical."},{"name":"Spellcasting","text":"The sphinx is a 9th-level spellcaster. Its spellcasting ability is Intelligence (spell save DC 16, +8 to hit with spell attacks). It requires no material components to cast its spells. The sphinx has the following wizard spells prepared:"}],"actions":[{"name":"Multiattack","text":"The sphinx makes two claw attacks."},{"name":"Claw","text":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) slashing damage.","attackBonus":8,"reach":"5 ft","damage":"2d8+4","damageType":"slashing"}],"legendaryActions":[{"name":"Claw Attack","text":"The sphinx makes one claw attack."},{"name":"Teleport (Costs 2 Actions)","text":"The sphinx magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."},{"name":"Cast a Spell (Costs 3 Actions)","text":"The sphinx casts a spell from its list of prepared spells, using a spell slot as normal."}],"legendaryCount":3}'),
    ('Half-Red Dragon Veteran', '/icons/monsters/_mono/H.svg', 'medium', 'humanoid', '{"name":"Half-Red Dragon Veteran","size":"medium","type":"humanoid","ac":18,"hp":65,"speed":{"walk":30},"abilities":{"str":16,"dex":13,"con":14,"int":10,"wis":11,"cha":10},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Plate","hitDice":"10d8 + 20","skills":[{"name":"Athletics","bonus":5},{"name":"Perception","bonus":2}],"damageResistances":["Fire"],"senses":["Blindsight 10 ft.","Darkvision 60 ft.","Passive Perception 12"],"languages":["Common","Draconic"],"actions":[{"name":"Multiattack","text":"The veteran makes two longsword attacks. If it has a shortsword drawn, it can also make a shortsword attack."},{"name":"Longsword","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) slashing damage, or 8 (1d10 + 3) slashing damage if used with two hands.","attackBonus":5,"reach":"5 ft","damage":"1d8+3","damageType":"slashing"},{"name":"Shortsword","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"piercing"},{"name":"Heavy Crossbow","text":"Ranged Weapon Attack: +3 to hit, range 100/400 ft., one target. Hit: 6 (1d10 + 1) piercing damage.","attackBonus":3,"reach":"range 100/400 ft","damage":"1d10+1","damageType":"piercing"},{"name":"Fire Breath (Recharge 5–6)","text":"The veteran exhales fire in a 15-foot cone. Each creature in that area must make a DC 15 Dexterity saving throw, taking 24 (7d6) fire damage on a failed save, or half as much damage on a successful one.","saveDc":15,"saveAbility":"dex"}]}'),
    ('Harpy', '/icons/monsters/_mono/H.svg', 'medium', 'monstrosity', '{"name":"Harpy","size":"medium","type":"monstrosity","ac":11,"hp":38,"speed":{"walk":20,"fly":40},"abilities":{"str":12,"dex":13,"con":12,"int":7,"wis":10,"cha":13},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","hitDice":"7d8 + 7","senses":["Passive Perception 10"],"languages":["Common"],"actions":[{"name":"Multiattack","text":"The harpy makes two attacks: one with its claws and one with its club."},{"name":"Claws","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 6 (2d4 + 1) slashing damage.","attackBonus":3,"reach":"5 ft","damage":"2d4+1","damageType":"slashing"},{"name":"Club","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 3 (1d4 + 1) bludgeoning damage.","attackBonus":3,"reach":"5 ft","damage":"1d4+1","damageType":"bludgeoning"},{"name":"Luring Song","text":"The harpy sings a magical melody. Every humanoid and giant within 300 feet of the harpy that can hear the song must succeed on a DC 11 Wisdom saving throw or be charmed until the song ends. The harpy must take a bonus action on its subsequent turns to continue singing. It can stop singing at any time. The song ends if the harpy is incapacitated.","saveDc":11,"saveAbility":"wis"}]}'),
    ('Hawk', '/icons/monsters/_mono/H.svg', 'tiny', 'beast', '{"name":"Hawk","size":"tiny","type":"beast","ac":13,"hp":1,"speed":{"walk":10,"fly":60},"abilities":{"str":5,"dex":16,"con":8,"int":2,"wis":14,"cha":6},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4 - 1","skills":[{"name":"Perception","bonus":4}],"senses":["Passive Perception 14"],"languages":["--"],"traits":[{"name":"Keen Sight","text":"The hawk has advantage on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Talons","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 1 slashing damage.","attackBonus":5,"reach":"5 ft"}]}'),
    ('Hell Hound', '/icons/monsters/_mono/H.svg', 'medium', 'fiend', '{"name":"Hell Hound","size":"medium","type":"fiend","ac":15,"hp":45,"speed":{"walk":50},"abilities":{"str":17,"dex":12,"con":14,"int":6,"wis":13,"cha":6},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"7d8 + 14","skills":[{"name":"Perception","bonus":5}],"damageImmunities":["Fire"],"senses":["Darkvision 60 ft.","Passive Perception 15"],"languages":["Understands Infernal but can''t speak it"],"traits":[{"name":"Keen Hearing and Smell","text":"The hound has advantage on Wisdom (Perception) checks that rely on hearing or smell."},{"name":"Pack Tactics","text":"The hound has advantage on an attack roll against a creature if at least one of the hound''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) piercing damage plus 7 (2d6) fire damage.","attackBonus":5,"reach":"5 ft","damage":"1d8+3","damageType":"piercing"},{"name":"Fire Breath (Recharge 5–6)","text":"The hound exhales fire in a 15-foot cone. Each creature in that area must make a DC 12 Dexterity saving throw, taking 21 (6d6) fire damage on a failed save, or half as much damage on a successful one.","saveDc":12,"saveAbility":"dex"}]}'),
    ('Hezrou', '/icons/monsters/_mono/H.svg', 'large', 'fiend', '{"name":"Hezrou","size":"large","type":"fiend","ac":16,"hp":136,"speed":{"walk":30},"abilities":{"str":19,"dex":17,"con":20,"int":5,"wis":12,"cha":13},"cr":"8","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"13d10 + 65","saves":{"str":7,"con":8,"wis":4},"damageResistances":["Cold","Fire","Lightning","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 11"],"languages":["Abyssal","Telepathy 120 ft."],"traits":[{"name":"Magic Resistance","text":"The hezrou has advantage on saving throws against spells and other magical effects."},{"name":"Stench","text":"Any creature that starts its turn within 10 feet of the hezrou must succeed on a DC 14 Constitution saving throw or be poisoned until the start of its next turn. On a successful saving throw, the creature is immune to the hezrou''s stench for 24 hours."}],"actions":[{"name":"Multiattack","text":"The hezrou makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 15 (2d10 + 4) piercing damage.","attackBonus":7,"reach":"5 ft","damage":"2d10+4","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d6+4","damageType":"slashing"}]}'),
    ('Hill Giant', '/icons/monsters/_mono/H.svg', 'huge', 'giant', '{"name":"Hill Giant","size":"huge","type":"giant","ac":13,"hp":105,"speed":{"walk":40},"abilities":{"str":21,"dex":8,"con":19,"int":5,"wis":9,"cha":6},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"10d12 + 40","skills":[{"name":"Perception","bonus":2}],"senses":["Passive Perception 12"],"languages":["Giant"],"actions":[{"name":"Multiattack","text":"The giant makes two greatclub attacks."},{"name":"Greatclub","text":"Melee Weapon Attack: +8 to hit, reach 10 ft., one target. Hit: 18 (3d8 + 5) bludgeoning damage.","attackBonus":8,"reach":"10 ft","damage":"3d8+5","damageType":"bludgeoning"},{"name":"Rock","text":"Ranged Weapon Attack: +8 to hit, range 60/240 ft., one target. Hit: 21 (3d10 + 5) bludgeoning damage.","attackBonus":8,"reach":"range 60/240 ft","damage":"3d10+5","damageType":"bludgeoning"}]}'),
    ('Hippogriff', '/icons/monsters/_mono/H.svg', 'large', 'monstrosity', '{"name":"Hippogriff","size":"large","type":"monstrosity","ac":11,"hp":19,"speed":{"walk":40,"fly":60},"abilities":{"str":17,"dex":13,"con":13,"int":2,"wis":12,"cha":8},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"3d10 + 3","skills":[{"name":"Perception","bonus":5}],"senses":["Passive Perception 15"],"languages":["--"],"traits":[{"name":"Keen Sight","text":"The hippogriff has advantage on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Multiattack","text":"The hippogriff makes two attacks: one with its beak and one with its claws."},{"name":"Beak","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (1d10 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d10+3","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"slashing"}]}'),
    ('Hobgoblin', '/icons/monsters/_mono/H.svg', 'medium', 'humanoid', '{"name":"Hobgoblin","size":"medium","type":"humanoid","ac":18,"hp":11,"speed":{"walk":30},"abilities":{"str":13,"dex":12,"con":12,"int":10,"wis":10,"cha":9},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Chain Mail, Shield","hitDice":"2d8 + 2","senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Common","Goblin"],"traits":[{"name":"Martial Advantage","text":"Once per turn, the hobgoblin can deal an extra 7 (2d6) damage to a creature it hits with a weapon attack if that creature is within 5 feet of an ally of the hobgoblin that isn''t incapacitated."}],"actions":[{"name":"Longsword","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 5 (1d8 + 1) slashing damage, or 6 (1d10 + 1) slashing damage if used with two hands.","attackBonus":3,"reach":"5 ft","damage":"1d8+1","damageType":"slashing"},{"name":"Longbow","text":"Ranged Weapon Attack: +3 to hit, range 150/600 ft., one target. Hit: 5 (1d8 + 1) piercing damage.","attackBonus":3,"reach":"range 150/600 ft","damage":"1d8+1","damageType":"piercing"}]}'),
    ('Homunculus', '/icons/monsters/_mono/H.svg', 'tiny', 'construct', '{"name":"Homunculus","size":"tiny","type":"construct","ac":13,"hp":5,"speed":{"walk":20,"fly":40},"abilities":{"str":4,"dex":15,"con":11,"int":10,"wis":10,"cha":7},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"Natural Armor","hitDice":"2d4","damageImmunities":["Poison"],"conditionImmunities":["Charmed","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Understands the languages of its creator but can''t speak"],"traits":[{"name":"Telepathic Bond","text":"While the homunculus is on the same plane of existence as its master, it can magically convey what it senses to its master, and the two can communicate telepathically."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 1 piercing damage, and the target must succeed on a DC 10 Constitution saving throw or be poisoned for 1 minute. If the saving throw fails by 5 or more, the target is instead poisoned for 5 (1d10) minutes and unconscious while poisoned in this way.","attackBonus":4,"reach":"5 ft","saveDc":10,"saveAbility":"con"}]}'),
    ('Horned Devil', '/icons/monsters/_mono/H.svg', 'large', 'fiend', '{"name":"Horned Devil","size":"large","type":"fiend","ac":18,"hp":148,"speed":{"walk":20,"fly":60},"abilities":{"str":22,"dex":17,"con":21,"int":12,"wis":16,"cha":17},"cr":"11","proficiencyBonus":4,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"17d10 + 55","saves":{"str":10,"dex":7,"wis":7,"cha":7},"damageResistances":["Cold","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"damageImmunities":["Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 13"],"languages":["Infernal","Telepathy 120 ft."],"traits":[{"name":"Devil''s Sight","text":"Magical darkness doesn''t impede the devil''s darkvision."},{"name":"Magic Resistance","text":"The devil has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The devil makes three melee attacks: two with its fork and one with its tail. It can use Hurl Flame in place of any melee attack."},{"name":"Fork","text":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 15 (2d8 + 6) piercing damage.","attackBonus":10,"reach":"10 ft","damage":"2d8+6","damageType":"piercing"},{"name":"Tail","text":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 10 (1d8 + 6) piercing damage. If the target is a creature other than an undead or a construct, it must succeed on a DC 17 Constitution saving throw or lose 10 (3d6) hit points at the start of each of its turns due to an infernal wound. Each time the devil hits the wounded target with this attack, the damage dealt by the wound increases by 10 (3d6). Any creature can take an action to stanch the wound with a successful DC 12 Wisdom (Medicine) check. The wound also closes if the target receives magical healing.","attackBonus":10,"reach":"10 ft","damage":"1d8+6","damageType":"piercing","saveDc":17,"saveAbility":"con"},{"name":"Hurl Flame","text":"Ranged Spell Attack: +7 to hit, range 150 ft., one target. Hit: 14 (4d6) fire damage. If the target is a flammable object that isn''t being worn or carried, it also catches fire.","attackBonus":7,"damage":"4d6","damageType":"fire"}]}'),
    ('Hunter Shark', '/icons/monsters/_mono/H.svg', 'large', 'beast', '{"name":"Hunter Shark","size":"large","type":"beast","ac":12,"hp":45,"speed":{"walk":0,"swim":40},"abilities":{"str":18,"dex":13,"con":15,"int":1,"wis":10,"cha":4},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"6d10 + 12","skills":[{"name":"Perception","bonus":2}],"senses":["Blindsight 30 ft.","Passive Perception 12"],"languages":["--"],"traits":[{"name":"Blood Frenzy","text":"The shark has advantage on melee attack rolls against any creature that doesn''t have all its hit points."},{"name":"Water Breathing","text":"The shark can breathe only underwater."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"2d8+4","damageType":"piercing"}]}'),
    ('Hydra', '/icons/monsters/_mono/H.svg', 'huge', 'monstrosity', '{"name":"Hydra","size":"huge","type":"monstrosity","ac":15,"hp":172,"speed":{"walk":30,"swim":30},"abilities":{"str":20,"dex":12,"con":20,"int":2,"wis":10,"cha":7},"cr":"8","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"15d12 + 75","skills":[{"name":"Perception","bonus":6}],"senses":["Darkvision 60 ft.","Passive Perception 16"],"languages":["--"],"traits":[{"name":"Hold Breath","text":"The hydra can hold its breath for 1 hour."},{"name":"Multiple Heads","text":"The hydra has five heads. While it has more than one head, the hydra has advantage on saving throws against being blinded, charmed, deafened, frightened, stunned, and knocked unconscious."},{"name":"Reactive Heads","text":"For each head the hydra has beyond one, it gets an extra reaction that can be used only for opportunity attacks."},{"name":"Wakeful","text":"While the hydra sleeps, at least one of its heads is awake."}],"actions":[{"name":"Multiattack","text":"The hydra makes as many bite attacks as it has heads."},{"name":"Bite","text":"Melee Weapon Attack: +8 to hit, reach 10 ft., one target. Hit: 10 (1d10 + 5) piercing damage.","attackBonus":8,"reach":"10 ft","damage":"1d10+5","damageType":"piercing"}]}'),
    ('Hyena', '/icons/monsters/_mono/H.svg', 'medium', 'beast', '{"name":"Hyena","size":"medium","type":"beast","ac":11,"hp":5,"speed":{"walk":50},"abilities":{"str":11,"dex":13,"con":12,"int":2,"wis":12,"cha":5},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d8 + 1","skills":[{"name":"Perception","bonus":3}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Pack Tactics","text":"The hyena has advantage on an attack roll against a creature if at least one of the hyena''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 3 (1d6) piercing damage.","attackBonus":2,"reach":"5 ft","damage":"1d6","damageType":"piercing"}]}'),
    ('Ice Devil', '/icons/monsters/_mono/I.svg', 'large', 'fiend', '{"name":"Ice Devil","size":"large","type":"fiend","ac":18,"hp":180,"speed":{"walk":40},"abilities":{"str":21,"dex":14,"con":18,"int":18,"wis":15,"cha":18},"cr":"14","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"19d10 + 76","saves":{"dex":7,"con":9,"wis":7,"cha":9},"damageResistances":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"damageImmunities":["Cold","Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Blindsight 60 ft.","Darkvision 120 ft.","Passive Perception 12"],"languages":["Infernal","Telepathy 120 ft."],"traits":[{"name":"Devil''s Sight","text":"Magical darkness doesn''t impede the devil''s darkvision."},{"name":"Magic Resistance","text":"The devil has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The devil makes three attacks: one with its bite, one with its claws, and one with its tail."},{"name":"Bite","text":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 12 (2d6 + 5) piercing damage plus 10 (3d6) cold damage.","attackBonus":10,"reach":"5 ft","damage":"2d6+5","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 10 (2d4 + 5) slashing damage plus 10 (3d6) cold damage.","attackBonus":10,"reach":"5 ft","damage":"2d4+5","damageType":"slashing"},{"name":"Tail","text":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 12 (2d6 + 5) bludgeoning damage plus 10 (3d6) cold damage.","attackBonus":10,"reach":"10 ft","damage":"2d6+5","damageType":"bludgeoning"},{"name":"Wall of Ice (Recharge 6)","text":"The devil magically forms an opaque wall of ice on a solid surface it can see within 60 feet of it. The wall is 1 foot thick and up to 30 feet long and 10 feet high, or it''s a hemispherical dome up to 20 feet in diameter."}]}'),
    ('Ice Mephit', '/icons/monsters/_mono/I.svg', 'small', 'elemental', '{"name":"Ice Mephit","size":"small","type":"elemental","ac":11,"hp":21,"speed":{"walk":30,"fly":30},"abilities":{"str":7,"dex":13,"con":10,"int":9,"wis":11,"cha":12},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"6d6","skills":[{"name":"Perception","bonus":2},{"name":"Stealth","bonus":3}],"damageImmunities":["Cold","Poison"],"damageVulnerabilities":["Bludgeoning","Fire"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 12"],"languages":["Aquan","Auran"],"traits":[{"name":"Death Burst","text":"When the mephit dies, it explodes in a burst of jagged ice. Each creature within 5 feet of it must make a DC 10 Dexterity saving throw, taking 4 (1d8) slashing damage on a failed save, or half as much damage on a successful one."},{"name":"False Appearance","text":"While the mephit remains motionless, it is indistinguishable from an ordinary shard of ice."},{"name":"Innate Spellcasting","text":"(1/Day). The mephit can innately cast fog cloud, requiring no material components. Its innate spellcasting ability is Charisma."}],"actions":[{"name":"Claws","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 3 (1d4 + 1) slashing damage plus 2 (1d4) cold damage.","attackBonus":3,"reach":"5 ft","damage":"1d4+1","damageType":"slashing"},{"name":"Frost Breath (Recharge 6)","text":"The mephit exhales a 15- foot cone of cold air. Each creature in that area must succeed on a DC 10 Dexterity saving throw, taking 5 (2d4) cold damage on a failed save, or half as much damage on a successful one.","saveDc":10,"saveAbility":"dex"}]}'),
    ('Imp', '/icons/monsters/_mono/I.svg', 'tiny', 'fiend', '{"name":"Imp","size":"tiny","type":"fiend","ac":13,"hp":10,"speed":{"walk":20,"fly":40},"abilities":{"str":6,"dex":17,"con":13,"int":11,"wis":12,"cha":14},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","hitDice":"3d4 + 3","skills":[{"name":"Deception","bonus":4},{"name":"Insight","bonus":3},{"name":"Persuasion","bonus":4},{"name":"Stealth","bonus":5}],"damageResistances":["Cold","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"damageImmunities":["Fire","Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 11"],"languages":["Common","Infernal"],"traits":[{"name":"Shapechanger","text":"The imp can use its action to polymorph into a beast form that resembles a rat (speed 20 ft.), a raven (20 ft., fly 60 ft.), or a spider (20 ft., climb 20 ft.), or back into its true form. Its statistics are the same in each form, except for the speed changes noted. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."},{"name":"Devil''s Sight","text":"Magical darkness doesn''t impede the imp''s darkvision."},{"name":"Magic Resistance","text":"The imp has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Sting (Bite in Beast Form)","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 5 (1d4 + 3) piercing damage, and the target must make on a DC 11 Constitution saving throw, taking 10 (3d6) poison damage on a failed save, or half as much damage on a successful one.","attackBonus":5,"reach":"5 ft","damage":"1d4+3","damageType":"piercing","saveDc":11,"saveAbility":"con"},{"name":"Invisibility","text":"The imp magically turns invisible until it attacks or until its concentration ends (as if concentrating on a spell). Any equipment the imp wears or carries is invisible with it."}]}'),
    ('Invisible Stalker', '/icons/monsters/_mono/I.svg', 'medium', 'elemental', '{"name":"Invisible Stalker","size":"medium","type":"elemental","ac":14,"hp":104,"speed":{"walk":50,"fly":50,"hover":true},"abilities":{"str":16,"dex":19,"con":14,"int":10,"wis":15,"cha":11},"cr":"6","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","hitDice":"16d8 + 32","skills":[{"name":"Perception","bonus":8},{"name":"Stealth","bonus":10}],"damageResistances":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Poison"],"conditionImmunities":["Exhaustion","Grappled","Paralyzed","Petrified","Poisoned","Prone","Restrained","Unconscious"],"senses":["Darkvision 60 ft.","Passive Perception 18"],"languages":["Auran  Understands Common but doesn''t speak it"],"traits":[{"name":"Invisibility","text":"The stalker is invisible."},{"name":"Faultless Tracker","text":"The stalker is given a quarry by its summoner. The stalker knows the direction and distance to its quarry as long as the two of them are on the same plane of existence. The stalker also knows the location of its summoner."}],"actions":[{"name":"Multiattack","text":"The stalker makes two slam attacks."},{"name":"Slam","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) bludgeoning damage.","attackBonus":6,"reach":"5 ft","damage":"2d6+3","damageType":"bludgeoning"}]}'),
    ('Iron Golem', '/icons/monsters/_mono/I.svg', 'large', 'construct', '{"name":"Iron Golem","size":"large","type":"construct","ac":20,"hp":210,"speed":{"walk":30},"abilities":{"str":24,"dex":9,"con":20,"int":3,"wis":11,"cha":1},"cr":"16","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"20d10 + 100","damageImmunities":["Fire","Poison","Psychic","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Adamantine"],"conditionImmunities":["Charmed","Exhaustion","Frightened","Paralyzed","Petrified","Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 10"],"languages":["Understands the languages of its creator but can''t speak"],"traits":[{"name":"Fire Absorption","text":"Whenever the golem is subjected to fire damage, it takes no damage and instead regains a number of hit points equal to the fire damage dealt."},{"name":"Immutable Form","text":"The golem is immune to any spell or effect that would alter its form."},{"name":"Magic Resistance","text":"The golem has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","text":"The golem''s weapon attacks are magical."}],"actions":[{"name":"Multiattack","text":"The golem makes two melee attacks."},{"name":"Slam","text":"Melee Weapon Attack: +13 to hit, reach 5 ft., one target. Hit: 20 (3d8 + 7) bludgeoning damage.","attackBonus":13,"reach":"5 ft","damage":"3d8+7","damageType":"bludgeoning"},{"name":"Sword","text":"Melee Weapon Attack: +13 to hit, reach 10 ft., one target. Hit: 23 (3d10 + 7) slashing damage.","attackBonus":13,"reach":"10 ft","damage":"3d10+7","damageType":"slashing"},{"name":"Poison Breath (Recharge 6)","text":"The golem exhales poisonous gas in a 15-foot cone. Each creature in that area must make a DC 19 Constitution saving throw, taking 45 (10d8) poison damage on a failed save, or half as much damage on a successful one.","saveDc":19,"saveAbility":"con"}]}'),
    ('Jackal', '/icons/monsters/_mono/J.svg', 'small', 'beast', '{"name":"Jackal","size":"small","type":"beast","ac":12,"hp":3,"speed":{"walk":40},"abilities":{"str":8,"dex":15,"con":11,"int":3,"wis":12,"cha":6},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d6","skills":[{"name":"Perception","bonus":3}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Hearing and Smell","text":"The jackal has advantage on Wisdom (Perception) checks that rely on hearing or smell."},{"name":"Pack Tactics","text":"The jackal has advantage on an attack roll against a creature if at least one of the jackal''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +1 to hit, reach 5 ft., one target. Hit: 1 (1d4 – 1) piercing damage.","attackBonus":1,"reach":"5 ft"}]}'),
    ('Killer Whale', '/icons/monsters/_mono/K.svg', 'huge', 'beast', '{"name":"Killer Whale","size":"huge","type":"beast","ac":12,"hp":90,"speed":{"walk":0,"swim":60},"abilities":{"str":19,"dex":10,"con":13,"int":3,"wis":12,"cha":7},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"12d12 + 12","skills":[{"name":"Perception","bonus":3}],"senses":["Blindsight 120 ft.","Passive Perception 13"],"languages":["--"],"traits":[{"name":"Echolocation","text":"The whale can''t use its blindsight while deafened."},{"name":"Hold Breath","text":"The whale can hold its breath for 30 minutes."},{"name":"Keen Hearing","text":"The whale has advantage on Wisdom (Perception) checks that rely on hearing."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 21 (5d6 + 4) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"5d6+4","damageType":"piercing"}]}'),
    ('Knight', '/icons/monsters/_mono/K.svg', 'medium', 'humanoid', '{"name":"Knight","size":"medium","type":"humanoid","ac":18,"hp":52,"speed":{"walk":30},"abilities":{"str":16,"dex":11,"con":14,"int":11,"wis":11,"cha":15},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Plate","hitDice":"8d8 + 16","saves":{"con":4,"wis":2},"senses":["Passive Perception 10"],"languages":["Any one language (usually Common)"],"traits":[{"name":"Brave","text":"The knight has advantage on saving throws against being frightened."}],"actions":[{"name":"Multiattack","text":"The knight makes two melee attacks."},{"name":"Greatsword","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"slashing"},{"name":"Heavy Crossbow","text":"Ranged Weapon Attack: +2 to hit, range 100/400 ft., one target. Hit: 5 (1d10) piercing damage.","attackBonus":2,"reach":"range 100/400 ft","damage":"1d10","damageType":"piercing"},{"name":"Leadership (Recharges after a Short or Long Rest)","text":"For 1 minute, the knight can utter a special command or warning whenever a nonhostile creature that it can see within 30 feet of it makes an attack roll or a saving throw. The creature can add a d4 to its roll provided it can hear and understand the knight. A creature can benefit from only one Leadership die at a time. This effect ends if the knight is incapacitated."}],"reactions":[{"name":"Parry","text":"The knight adds 2 to its AC against one melee attack that would hit it. To do so, the knight must see the attacker and be wielding a melee weapon."}]}'),
    ('Kobold', '/icons/monsters/_mono/K.svg', 'small', 'humanoid', '{"name":"Kobold","size":"small","type":"humanoid","ac":12,"hp":5,"speed":{"walk":30},"abilities":{"str":7,"dex":15,"con":9,"int":8,"wis":7,"cha":8},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","hitDice":"2d6 - 2","senses":["Darkvision 60 ft.","Passive Perception 8"],"languages":["Common","Draconic"],"traits":[{"name":"Sunlight Sensitivity","text":"While in sunlight, the kobold has disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."},{"name":"Pack Tactics","text":"The kobold has advantage on an attack roll against a creature if at least one of the kobold''s allies is within 5 feet of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Dagger","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d4+2","damageType":"piercing"},{"name":"Sling","text":"Ranged Weapon Attack: +4 to hit, range 30/120 ft., one target. Hit: 4 (1d4 + 2) bludgeoning damage.","attackBonus":4,"reach":"range 30/120 ft","damage":"1d4+2","damageType":"bludgeoning"}]}'),
    ('Kraken', '/icons/monsters/_mono/K.svg', 'gargantuan', 'monstrosity', '{"name":"Kraken","size":"gargantuan","type":"monstrosity","ac":18,"hp":472,"speed":{"walk":20,"swim":60},"abilities":{"str":30,"dex":11,"con":25,"int":22,"wis":18,"cha":20},"cr":"23","proficiencyBonus":7,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"27d20 + 189","saves":{"str":17,"dex":7,"con":14,"int":13,"wis":11},"damageImmunities":["Lightning","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"conditionImmunities":["Frightened","Paralyzed"],"senses":["Truesight 120 ft.","Passive Perception 14"],"languages":["Abyssal","Celestial","Infernal","Primordial","Telepathy 120 ft. but can''t speak"],"traits":[{"name":"Amphibious","text":"The kraken can breathe air and water."},{"name":"Freedom of Movement","text":"The kraken ignores difficult terrain, and magical effects can''t reduce its speed or cause it to be restrained. It can spend 5 feet of movement to escape from nonmagical restraints or being grappled."},{"name":"Siege Monster","text":"The kraken deals double damage to objects and structures."}],"actions":[{"name":"Multiattack","text":"The kraken makes three tentacle attacks, each of which it can replace with one use of Fling."},{"name":"Bite","text":"Melee Weapon Attack: +17 to hit, reach 5 ft., one target. Hit: 23 (3d8 + 10) piercing damage. If the target is a Large or smaller creature grappled by the kraken, that creature is swallowed, and the grapple ends. While swallowed, the creature is blinded and restrained, it has total cover against attacks and other effects outside the kraken, and it takes 42 (12d6) acid damage at the start of each of the kraken''s turns.","attackBonus":17,"reach":"5 ft","damage":"3d8+10","damageType":"piercing"},{"name":"Tentacle","text":"Melee Weapon Attack: +17 to hit, reach 30 ft., one target. Hit: 20 (3d6 + 10) bludgeoning damage, and the target is grappled (escape DC 18). Until this grapple ends, the target is restrained. The kraken has ten tentacles, each of which can grapple one target.","attackBonus":17,"reach":"30 ft","damage":"3d6+10","damageType":"bludgeoning"},{"name":"Fling","text":"One Large or smaller object held or creature grappled by the kraken is thrown up to 60 feet in a random direction and knocked prone. If a thrown target strikes a solid surface, the target takes 3 (1d6) bludgeoning damage for every 10 feet it was thrown. If the target is thrown at another creature, that creature must succeed on a DC 18 Dexterity saving throw or take the same damage and be knocked prone.","saveDc":18,"saveAbility":"dex"},{"name":"Lightning Storm","text":"The kraken magically creates three bolts of lightning, each of which can strike a target the kraken can see within 120 feet of it. A target must make a DC 23 Dexterity saving throw, taking 22 (4d10) lightning damage on a failed save, or half as much damage on a successful one.","saveDc":23,"saveAbility":"dex"}],"legendaryActions":[{"name":"Tentacle Attack or Fling","text":"The kraken makes one tentacle attack or uses its Fling."},{"name":"Lightning Storm (Costs 2 Actions)","text":"The kraken uses Lightning Storm."},{"name":"Ink Cloud (Costs 3 Actions)","text":"While underwater, the kraken expels an ink cloud in a 60-foot radius. The cloud spreads around corners, and that area is heavily obscured to creatures other than the kraken. Each creature other than the kraken that ends its turn there must succeed on a DC 23 Constitution saving throw, taking 16 (3d10) poison damage on a failed save, or half as much damage on a successful one. A strong current disperses the cloud, which otherwise disappears at the end of the kraken''s next turn."}],"legendaryCount":3}'),
    ('Lamia', '/icons/monsters/_mono/L.svg', 'large', 'monstrosity', '{"name":"Lamia","size":"large","type":"monstrosity","ac":13,"hp":97,"speed":{"walk":30},"abilities":{"str":16,"dex":13,"con":15,"int":14,"wis":15,"cha":16},"cr":"4","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"13d10 + 26","skills":[{"name":"Deception","bonus":7},{"name":"Insight","bonus":4},{"name":"Stealth","bonus":3}],"senses":["Darkvision 60 ft.","Passive Perception 12"],"languages":["Abyssal","Common"],"traits":[{"name":"Innate Spellcasting","text":"The lamia''s innate spellcasting ability is Charisma (spell save DC 13). It can innately cast the following spells, requiring no material components."}],"actions":[{"name":"Multiattack","text":"The lamia makes two attacks: one with its claws and one with its dagger or Intoxicating Touch."},{"name":"Claws","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 14 (2d10 + 3) slashing damage. Dagger. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 5 (1d4 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"2d10+3","damageType":"slashing"},{"name":"Intoxicating Touch","text":"Melee Spell Attack: +5 to hit, reach 5 ft., one creature. Hit: The target is magically cursed for 1 hour. Until the curse ends, the target has disadvantage on Wisdom saving throws and all ability checks.","attackBonus":5,"reach":"5 ft"}]}'),
    ('Lemure', '/icons/monsters/_mono/L.svg', 'medium', 'fiend', '{"name":"Lemure","size":"medium","type":"fiend","ac":7,"hp":13,"speed":{"walk":15},"abilities":{"str":10,"dex":5,"con":11,"int":1,"wis":11,"cha":3},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","hitDice":"3d8","damageResistances":["Cold"],"damageImmunities":["Fire","Poison"],"conditionImmunities":["Charmed","Frightened","Poisoned"],"senses":["Darkvision 120 ft.","Passive Perception 10"],"languages":["Understands Infernal but can''t speak it"],"traits":[{"name":"Devil''s Sight","text":"Magical darkness doesn''t impede the lemure''s darkvision."},{"name":"Hellish Rejuvenation","text":"A lemure that dies in the Nine Hells comes back to life with all its hit points in 1d10 days unless it is killed by a good-aligned creature with a bless spell cast on that creature or its remains are sprinkled with holy water."}],"actions":[{"name":"Fist","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 2 (1d4) bludgeoning damage.","attackBonus":3,"reach":"5 ft","damage":"1d4","damageType":"bludgeoning"}]}'),
    ('Lich', '/icons/monsters/_mono/L.svg', 'medium', 'undead', '{"name":"Lich","size":"medium","type":"undead","ac":17,"hp":135,"speed":{"walk":30},"abilities":{"str":11,"dex":16,"con":16,"int":20,"wis":14,"cha":16},"cr":"21","proficiencyBonus":7,"source":"SRD 5.1, CC-BY-4.0","alignment":"any evil alignment","acNote":"Natural Armor","hitDice":"18d8 + 54","saves":{"con":10,"int":12,"wis":9},"skills":[{"name":"Arcana","bonus":18},{"name":"History","bonus":12},{"name":"Insight","bonus":9},{"name":"Perception","bonus":9}],"damageResistances":["Cold","Lightning","Necrotic"],"damageImmunities":["Poison","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"conditionImmunities":["Charmed","Exhaustion","Frightened","Paralyzed","Poisoned"],"senses":["Truesight 120 ft.","Passive Perception 19"],"languages":["Common plus up to five other languages"],"traits":[{"name":"Legendary Resistance (3/Day)","text":"If the lich fails a saving throw, it can choose to succeed instead."},{"name":"Rejuvenation","text":"If it has a phylactery, a destroyed lich gains a new body in 1d10 days, regaining all its hit points and becoming active again. The new body appears within 5 feet of the phylactery."},{"name":"Spellcasting","text":"The lich is an 18th-level spellcaster. Its spellcasting ability is Intelligence (spell save DC 20, +12 to hit with spell attacks). The lich has the following wizard spells prepared:"},{"name":"Turn Resistance","text":"The lich has advantage on saving throws against any effect that turns undead."}],"actions":[{"name":"Paralyzing Touch","text":"Melee Spell Attack: +12 to hit, reach 5 ft., one creature. Hit: 10 (3d6) cold damage. The target must succeed on a DC 18 Constitution saving throw or be paralyzed for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attackBonus":12,"reach":"5 ft","damage":"3d6","damageType":"cold","saveDc":18,"saveAbility":"con"}],"legendaryActions":[{"name":"Cantrip","text":"The lich casts a cantrip."},{"name":"Paralyzing Touch (Costs 2 Actions)","text":"The lich uses its Paralyzing Touch."},{"name":"Frightening Gaze (Costs 2 Actions)","text":"The lich fixes its gaze on one creature it can see within 10 feet of it. The target must succeed on a DC 18 Wisdom saving throw against this magic or become frightened for 1 minute. The frightened target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a target''s saving throw is successful or the effect ends for it, the target is immune to the lich''s gaze for the next 24 hours."},{"name":"Disrupt Life (Costs 3 Actions)","text":"Each living creature within 20 feet of the lich must make a DC 18 Constitution saving throw against this magic, taking 21 (6d6) necrotic damage on a failed save, or half as much damage on a successful one."}],"legendaryCount":3}'),
    ('Lion', '/icons/monsters/_mono/L.svg', 'large', 'beast', '{"name":"Lion","size":"large","type":"beast","ac":12,"hp":26,"speed":{"walk":50},"abilities":{"str":17,"dex":15,"con":13,"int":3,"wis":12,"cha":8},"cr":"1","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"4d10 + 4","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":6}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Smell","text":"The lion has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Pack Tactics","text":": The lion has advantage on an attack roll against a creature if at least one of the lion''s allies is within 5 feet of the creature and the ally isn''t incapacitated."},{"name":"Pounce","text":"If the lion moves at least 20 feet straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a DC 13 Strength saving throw or be knocked prone. If the target is prone, the lion can make one bite attack against it as a bonus action."},{"name":"Running Leap","text":"With a 10-foot running start, the lion can long jump up to 25 feet."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d8+3","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"slashing"}]}'),
    ('Lizard', '/icons/monsters/_mono/L.svg', 'tiny', 'beast', '{"name":"Lizard","size":"tiny","type":"beast","ac":10,"hp":2,"speed":{"walk":20,"climb":20},"abilities":{"str":2,"dex":11,"con":10,"int":1,"wis":8,"cha":3},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d4","senses":["Darkvision 30 ft.","Passive Perception 9"],"languages":["--"],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +0 to hit, reach 5 ft., one target. Hit: 1 piercing damage.","attackBonus":0,"reach":"5 ft"}]}'),
    ('Lizardfolk', '/icons/monsters/_mono/L.svg', 'medium', 'humanoid', '{"name":"Lizardfolk","size":"medium","type":"humanoid","ac":15,"hp":22,"speed":{"walk":30,"swim":30},"abilities":{"str":15,"dex":10,"con":13,"int":7,"wis":12,"cha":7},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"Natural Armor, Shield","hitDice":"4d8 + 4","skills":[{"name":"Perception","bonus":3},{"name":"Stealth","bonus":2},{"name":"Survival","bonus":5}],"senses":["Passive Perception 13"],"languages":["Draconic"],"traits":[{"name":"Hold Breath","text":"The lizardfolk can hold its breath for 15 minutes."}],"actions":[{"name":"Multiattack","text":"The lizardfolk makes two melee attacks, each one with a different weapon."},{"name":"Bite","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Heavy Club","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) bludgeoning damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"bludgeoning"},{"name":"Javelin","text":"Melee or Ranged Weapon Attack: +4 to hit, reach 5 ft. or range 30/120 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Spiked Shield","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"}]}'),
    ('Mage', '/icons/monsters/_mono/M.svg', 'medium', 'humanoid', '{"name":"Mage","size":"medium","type":"humanoid","ac":12,"hp":40,"speed":{"walk":30},"abilities":{"str":9,"dex":14,"con":11,"int":17,"wis":12,"cha":11},"cr":"6","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"15 With Mage Armor","hitDice":"9d8","saves":{"int":6,"wis":4},"skills":[{"name":"Arcana","bonus":6},{"name":"History","bonus":6}],"senses":["Passive Perception 11"],"languages":["Any four languages"],"traits":[{"name":"Spellcasting","text":"The mage is a 9th-level spellcaster. Its spellcasting ability is Intelligence (spell save DC 14, +6 to hit with spell attacks). The mage has the following wizard spells prepared:"}],"actions":[{"name":"Dagger","text":"Melee or Ranged Weapon Attack: +5 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 4 (1d4 + 2) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d4+2","damageType":"piercing"}]}'),
    ('Magma Mephit', '/icons/monsters/_mono/M.svg', 'small', 'elemental', '{"name":"Magma Mephit","size":"small","type":"elemental","ac":11,"hp":22,"speed":{"walk":30,"fly":30},"abilities":{"str":8,"dex":12,"con":12,"int":7,"wis":10,"cha":10},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"5d6 + 5","skills":[{"name":"Stealth","bonus":3}],"damageImmunities":["Fire","Poison"],"damageVulnerabilities":["Cold"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Ignan","Terran"],"traits":[{"name":"Death Burst","text":"When the mephit dies, it explodes in a burst of lava. Each creature within 5 feet of it must make a DC 11 Dexterity saving throw, taking 7 (2d6) fire damage on a failed save, or half as much damage on a successful one."},{"name":"False Appearance","text":"While the mephit remains motionless, it is indistinguishable from an ordinary mound of magma."},{"name":"Innate Spellcasting","text":"(1/Day). The mephit can innately cast heat metal (spell save DC 10), requiring no material components. Its innate spellcasting ability is Charisma."}],"actions":[{"name":"Claws","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 3 (1d4 + 1) slashing damage plus 2 (1d4) fire damage.","attackBonus":3,"reach":"5 ft","damage":"1d4+1","damageType":"slashing"},{"name":"Fire Breath (Recharge 6)","text":"The mephit exhales a 15-foot cone of fire. Each creature in that area must make a DC 11 Dexterity saving throw, taking 7 (2d6) fire damage on a failed save, or half as much damage on a successful one.","saveDc":11,"saveAbility":"dex"}]}'),
    ('Magmin', '/icons/monsters/_mono/M.svg', 'small', 'elemental', '{"name":"Magmin","size":"small","type":"elemental","ac":14,"hp":9,"speed":{"walk":30},"abilities":{"str":7,"dex":15,"con":12,"int":8,"wis":11,"cha":10},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic neutral","acNote":"Natural Armor","hitDice":"2d6 + 2","damageResistances":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Fire"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Ignan"],"traits":[{"name":"Death Burst","text":"When the magmin dies, it explodes in a burst of fire and magma. Each creature within 10 feet of it must make a DC 11 Dexterity saving throw, taking 7 (2d6) fire damage on a failed save, or half as much damage on a successful one. Flammable objects that aren''t being worn or carried in that area are ignited."},{"name":"Ignited Illumination","text":"As a bonus action, the magmin can set itself ablaze or extinguish its flames. While ablaze, the magmin sheds bright light in a 10-foot radius and dim light for an additional 10 feet."}],"actions":[{"name":"Touch","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (2d6) fire damage. If the target is a creature or a flammable object, it ignites. Until a creature takes an action to douse the fire, the target takes 3 (1d6) fire damage at the end of each of its turns.","attackBonus":4,"reach":"5 ft","damage":"2d6","damageType":"fire"}]}'),
    ('Mammoth', '/icons/monsters/_mono/M.svg', 'huge', 'beast', '{"name":"Mammoth","size":"huge","type":"beast","ac":13,"hp":126,"speed":{"walk":40},"abilities":{"str":24,"dex":9,"con":21,"int":3,"wis":11,"cha":6},"cr":"6","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","acNote":"Natural Armor","hitDice":"11d12 + 55","senses":["Passive Perception 10"],"languages":["--"],"traits":[{"name":"Trampling Charge","text":"If the mammoth moves at least 20 feet straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a DC 18 Strength saving throw or be knocked prone. If the target is prone, the mammoth can make one stomp attack against it as a bonus action."}],"actions":[{"name":"Gore","text":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 25 (4d8 + 7) piercing damage.","attackBonus":10,"reach":"10 ft","damage":"4d8+7","damageType":"piercing"},{"name":"Stomp","text":"Melee Weapon Attack: +10 to hit, reach 5 ft., one prone creature. Hit: 29 (4d10 + 7) bludgeoning damage.","attackBonus":10,"reach":"5 ft","damage":"4d10+7","damageType":"bludgeoning"}]}'),
    ('Manticore', '/icons/monsters/_mono/M.svg', 'large', 'monstrosity', '{"name":"Manticore","size":"large","type":"monstrosity","ac":14,"hp":68,"speed":{"walk":30,"fly":50},"abilities":{"str":17,"dex":16,"con":17,"int":7,"wis":12,"cha":8},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"8d10 + 24","senses":["Darkvision 60 ft.","Passive Perception 11"],"languages":["Common"],"traits":[{"name":"Tail Spike Regrowth","text":"The manticore has twenty-four tail spikes. Used spikes regrow when the manticore finishes a long rest."}],"actions":[{"name":"Multiattack","text":"The manticore makes three attacks: one with its bite and two with its claws or three with its tail spikes."},{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d8+3","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"slashing"},{"name":"Tail Spike","text":"Ranged Weapon Attack: +5 to hit, range 100/200 ft., one target. Hit: 7 (1d8 + 3) piercing damage.","attackBonus":5,"reach":"range 100/200 ft","damage":"1d8+3","damageType":"piercing"}]}'),
    ('Marilith', '/icons/monsters/_mono/M.svg', 'large', 'fiend', '{"name":"Marilith","size":"large","type":"fiend","ac":18,"hp":189,"speed":{"walk":40},"abilities":{"str":18,"dex":20,"con":20,"int":18,"wis":16,"cha":20},"cr":"16","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"18d10 + 90","saves":{"str":9,"con":10,"wis":8,"cha":10},"damageResistances":["Cold","Fire","Lightning","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":["Truesight 120 ft.","Passive Perception 13"],"languages":["Abyssal","Telepathy 120 ft."],"traits":[{"name":"Magic Resistance","text":"The marilith has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","text":"The marilith''s weapon attacks are magical."},{"name":"Reactive","text":"The marilith can take one reaction on every turn in a combat."}],"actions":[{"name":"Multiattack","text":"The marilith makes seven attacks: six with its longswords and one with its tail."},{"name":"Longsword","text":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) slashing damage.","attackBonus":9,"reach":"5 ft","damage":"2d8+4","damageType":"slashing"},{"name":"Tail","text":"Melee Weapon Attack: +9 to hit, reach 10 ft., one creature. Hit: 15 (2d10 + 4) bludgeoning damage. If the target is Medium or smaller, it is grappled (escape DC 19). Until this grapple ends, the target is restrained, the marilith can automatically hit the target with its tail, and the marilith can''t make tail attacks against other targets.","attackBonus":9,"reach":"10 ft","damage":"2d10+4","damageType":"bludgeoning"},{"name":"Teleport","text":"The marilith magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."}],"reactions":[{"name":"Parry","text":"The marilith adds 5 to its AC against one melee attack that would hit it. To do so, the marilith must see the attacker and be wielding a melee weapon."}]}'),
    ('Mastiff', '/icons/monsters/_mono/M.svg', 'medium', 'beast', '{"name":"Mastiff","size":"medium","type":"beast","ac":12,"hp":5,"speed":{"walk":40},"abilities":{"str":13,"dex":14,"con":12,"int":3,"wis":12,"cha":7},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d8 + 1","skills":[{"name":"Perception","bonus":3}],"senses":["Passive Perception 13"],"languages":["--"],"traits":[{"name":"Keen Hearing and Smell","text":"The mastiff has advantage on Wisdom (Perception) checks that rely on hearing or smell."}],"actions":[{"name":"Bite","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) piercing damage. If the target is a creature, it must succeed on a DC 11 Strength saving throw or be knocked prone.","attackBonus":3,"reach":"5 ft","damage":"1d6+1","damageType":"piercing","saveDc":11,"saveAbility":"str"}]}'),
    ('Medusa', '/icons/monsters/_mono/M.svg', 'medium', 'monstrosity', '{"name":"Medusa","size":"medium","type":"monstrosity","ac":15,"hp":127,"speed":{"walk":30},"abilities":{"str":10,"dex":15,"con":16,"int":12,"wis":13,"cha":15},"cr":"6","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"17d8 + 51","skills":[{"name":"Deception","bonus":5},{"name":"Insight","bonus":4},{"name":"Perception","bonus":4},{"name":"Stealth","bonus":5}],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["Common"],"traits":[{"name":"Petrifying Gaze","text":"When a creature that can see the medusa''s eyes starts its turn within 30 feet of the medusa, the medusa can force it to make a DC 14 Constitution saving throw if the medusa isn''t incapacitated and can see the creature. If the saving throw fails by 5 or more, the creature is instantly petrified. Otherwise, a creature that fails the save begins to turn to stone and is restrained. The restrained creature must repeat the saving throw at the end of its next turn, becoming petrified on a failure or ending the effect on a success. The petrification lasts until the creature is freed by the greater restoration spell or other magic."}],"actions":[{"name":"Multiattack","text":"The medusa makes either three melee attacks--one with its snake hair and two with its shortsword--or two ranged attacks with its longbow."},{"name":"Snake Hair","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 4 (1d4 + 2) piercing damage plus 14 (4d6) poison damage.","attackBonus":5,"reach":"5 ft","damage":"1d4+2","damageType":"piercing"},{"name":"Shortsword","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+2","damageType":"piercing"},{"name":"Longbow","text":"Ranged Weapon Attack: +5 to hit, range 150/600 ft., one target. Hit: 6 (1d8 + 2) piercing damage plus 7 (2d6) poison damage.","attackBonus":5,"reach":"range 150/600 ft","damage":"1d8+2","damageType":"piercing"}]}'),
    ('Merfolk', '/icons/monsters/_mono/M.svg', 'medium', 'humanoid', '{"name":"Merfolk","size":"medium","type":"humanoid","ac":11,"hp":11,"speed":{"walk":10,"swim":40},"abilities":{"str":10,"dex":13,"con":12,"int":11,"wis":11,"cha":12},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","hitDice":"2d8 + 2","skills":[{"name":"Perception","bonus":2}],"senses":["Passive Perception 12"],"languages":["Aquan","Common"],"traits":[{"name":"Amphibious","text":"The merfolk can breathe air and water."}],"actions":[{"name":"Spear","text":"Melee or Ranged Weapon Attack: +2 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 3 (1d6) piercing damage, or 4 (1d8) piercing damage if used with two hands to make a melee attack.","attackBonus":2,"reach":"5 ft","damage":"1d6","damageType":"piercing"}]}'),
    ('Merrow', '/icons/monsters/_mono/M.svg', 'large', 'monstrosity', '{"name":"Merrow","size":"large","type":"monstrosity","ac":13,"hp":45,"speed":{"walk":10,"swim":40},"abilities":{"str":18,"dex":10,"con":15,"int":8,"wis":10,"cha":9},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"6d10 + 12","senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Abyssal","Aquan"],"traits":[{"name":"Amphibious","text":"The merrow can breathe air and water."}],"actions":[{"name":"Multiattack","text":"The merrow makes two attacks: one with its bite and one with its claws or harpoon."},{"name":"Bite","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 8 (1d8 + 4) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"1d8+4","damageType":"piercing"},{"name":"Claws","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (2d4 + 4) slashing damage.","attackBonus":6,"reach":"5 ft","damage":"2d4+4","damageType":"slashing"},{"name":"Harpoon","text":"Melee or Ranged Weapon Attack: +6 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 11 (2d6 + 4) piercing damage. If the target is a Huge or smaller creature, it must succeed on a Strength contest against the merrow or be pulled up to 20 feet toward the merrow.","attackBonus":6,"reach":"5 ft","damage":"2d6+4","damageType":"piercing"}]}'),
    ('Mimic', '/icons/monsters/_mono/M.svg', 'medium', 'monstrosity', '{"name":"Mimic","size":"medium","type":"monstrosity","ac":12,"hp":58,"speed":{"walk":15},"abilities":{"str":17,"dex":12,"con":15,"int":5,"wis":13,"cha":8},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral","acNote":"Natural Armor","hitDice":"9d8 + 18","skills":[{"name":"Stealth","bonus":5}],"damageImmunities":["Acid"],"conditionImmunities":["Prone"],"senses":["Darkvision 60 ft.","Passive Perception 11"],"languages":["--"],"traits":[{"name":"Shapechanger","text":"The mimic can use its action to polymorph into an object or back into its true, amorphous form. Its statistics are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."},{"name":"Adhesive (Object Form Only)","text":"The mimic adheres to anything that touches it. A Huge or smaller creature adhered to the mimic is also grappled by it (escape DC 13). Ability checks made to escape this grapple have disadvantage."},{"name":"False Appearance (Object Form Only)","text":"While the mimic remains motionless, it is indistinguishable from an ordinary object."},{"name":"Grappler","text":"The mimic has advantage on attack rolls against any creature grappled by it."}],"actions":[{"name":"Pseudopod","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) bludgeoning damage. If the mimic is in object form, the target is subjected to its Adhesive trait.","attackBonus":5,"reach":"5 ft","damage":"1d8+3","damageType":"bludgeoning"},{"name":"Bite","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) piercing damage plus 4 (1d8) acid damage.","attackBonus":5,"reach":"5 ft","damage":"1d8+3","damageType":"piercing"}]}'),
    ('Minotaur', '/icons/monsters/_mono/M.svg', 'large', 'monstrosity', '{"name":"Minotaur","size":"large","type":"monstrosity","ac":14,"hp":76,"speed":{"walk":40},"abilities":{"str":18,"dex":11,"con":16,"int":6,"wis":16,"cha":9},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"9d10 + 27","skills":[{"name":"Perception","bonus":7}],"senses":["Darkvision 60 ft.","Passive Perception 17"],"languages":["Abyssal"],"traits":[{"name":"Charge","text":"If the minotaur moves at least 10 feet straight toward a target and then hits it with a gore attack on the same turn, the target takes an extra 9 (2d8) piercing damage. If the target is a creature, it must succeed on a DC 14 Strength saving throw or be pushed up to 10 feet away and knocked prone."},{"name":"Labyrinthine Recall","text":"The minotaur can perfectly recall any path it has traveled."},{"name":"Reckless","text":"At the start of its turn, the minotaur can gain advantage on all melee weapon attack rolls it makes during that turn, but attack rolls against it have advantage until the start of its next turn."}],"actions":[{"name":"Greataxe","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 17 (2d12 + 4) slashing damage.","attackBonus":6,"reach":"5 ft","damage":"2d12+4","damageType":"slashing"},{"name":"Gore","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"2d8+4","damageType":"piercing"}]}'),
    ('Minotaur Skeleton', '/icons/monsters/_mono/M.svg', 'large', 'undead', '{"name":"Minotaur Skeleton","size":"large","type":"undead","ac":12,"hp":67,"speed":{"walk":40},"abilities":{"str":18,"dex":11,"con":15,"int":6,"wis":8,"cha":5},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"9d10 + 18","damageImmunities":["Poison"],"damageVulnerabilities":["Bludgeoning"],"conditionImmunities":["Exhaustion","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 9"],"languages":["Understands Abyssal but can''t speak  it"],"traits":[{"name":"Charge","text":"If the skeleton moves at least 10 feet straight toward a target and then hits it with a gore attack on the same turn, the target takes an extra 9 (2d8) piercing damage. If the target is a creature, it must succeed on a DC 14 Strength saving throw or be pushed up to 10 feet away and knocked prone."}],"actions":[{"name":"Greataxe","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 17 (2d12 + 4) slashing damage.","attackBonus":6,"reach":"5 ft","damage":"2d12+4","damageType":"slashing"},{"name":"Gore","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"2d8+4","damageType":"piercing"}]}'),
    ('Mule', '/icons/monsters/_mono/M.svg', 'medium', 'beast', '{"name":"Mule","size":"medium","type":"beast","ac":10,"hp":11,"speed":{"walk":40},"abilities":{"str":14,"dex":10,"con":13,"int":2,"wis":10,"cha":5},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"2d8 + 2","senses":["Passive Perception 10"],"languages":["--"],"traits":[{"name":"Beast of Burden","text":"The mule is considered to be a Large animal for the purpose of determining its carrying capacity."},{"name":"Sure-Footed","text":"The mule has advantage on Strength and Dexterity saving throws made against effects that would knock it prone."}],"actions":[{"name":"Hooves","text":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) bludgeoning damage.","attackBonus":2,"reach":"5 ft","damage":"1d4+2","damageType":"bludgeoning"}]}'),
    ('Mummy', '/icons/monsters/_mono/M.svg', 'medium', 'undead', '{"name":"Mummy","size":"medium","type":"undead","ac":11,"hp":58,"speed":{"walk":20},"abilities":{"str":16,"dex":8,"con":15,"int":6,"wis":10,"cha":12},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"9d8 + 18","saves":{"wis":2},"damageResistances":["Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Necrotic","Poison"],"damageVulnerabilities":["Fire"],"conditionImmunities":["Charmed","Exhaustion","Frightened","Paralyzed","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["The languages it knew in life"],"actions":[{"name":"Multiattack","text":"The mummy can use its Dreadful Glare and makes one attack with its rotting fist."},{"name":"Rotting Fist","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) bludgeoning damage plus 10 (3d6) necrotic damage. If the target is a creature, it must succeed on a DC 12 Constitution saving throw or be cursed with mummy rot. The cursed target can''t regain hit points, and its hit point maximum decreases by 10 (3d6) for every 24 hours that elapse. If the curse reduces the target''s hit point maximum to 0, the target dies, and its body turns to dust. The curse lasts until removed by the remove curse spell or other magic.","attackBonus":5,"reach":"5 ft","damage":"2d6+3","damageType":"bludgeoning","saveDc":12,"saveAbility":"con"},{"name":"Dreadful Glare","text":"The mummy targets one creature it can see within 60 feet of it. If the target can see the mummy, it must succeed on a DC 11 Wisdom saving throw against this magic or become frightened until the end of the mummy''s next turn. If the target fails the saving throw by 5 or more, it is also paralyzed for the same duration. A target that succeeds on the saving throw is immune to the Dreadful Glare of all mummies (but not mummy lords) for the next 24 hours.","saveDc":11,"saveAbility":"wis"}]}'),
    ('Mummy Lord', '/icons/monsters/_mono/M.svg', 'medium', 'undead', '{"name":"Mummy Lord","size":"medium","type":"undead","ac":17,"hp":97,"speed":{"walk":20},"abilities":{"str":18,"dex":10,"con":17,"int":11,"wis":18,"cha":16},"cr":"15","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Natural Armor","hitDice":"13d8 + 39","saves":{"con":8,"int":5,"wis":9,"cha":8},"skills":[{"name":"History","bonus":5},{"name":"Religion","bonus":5}],"damageImmunities":["Necrotic","Poison","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageVulnerabilities":["Fire"],"conditionImmunities":["Charmed","Exhaustion","Frightened","Paralyzed","Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["The languages it knew in life"],"traits":[{"name":"Magic Resistance","text":"The mummy lord has advantage on saving throws against spells and other magical effects."},{"name":"Rejuvenation","text":"A destroyed mummy lord gains a new body in 24 hours if its heart is intact, regaining all its hit points and becoming active again. The new body appears within 5 feet of the mummy lord''s heart."},{"name":"Spellcasting","text":"The mummy lord is a 10th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 17, +9 to hit with spell attacks). The mummy lord has the following cleric spells prepared:"}],"actions":[{"name":"Multiattack","text":"The mummy can use its Dreadful Glare and makes one attack with its rotting fist."},{"name":"Rotting Fist","text":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 14 (3d6 + 4) bludgeoning damage plus 21 (6d6) necrotic damage. If the target is a creature, it must succeed on a DC 16 Constitution saving throw or be cursed with mummy rot. The cursed target can''t regain hit points, and its hit point maximum decreases by 10 (3d6) for every 24 hours that elapse. If the curse reduces the target''s hit point maximum to 0, the target dies, and its body turns to dust. The curse lasts until removed by the remove curse spell or other magic.","attackBonus":9,"reach":"5 ft","damage":"3d6+4","damageType":"bludgeoning","saveDc":16,"saveAbility":"con"},{"name":"Dreadful Glare","text":"The mummy lord targets one creature it can see within 60 feet of it. If the target can see the mummy lord, it must succeed on a DC 16 Wisdom saving throw against this magic or become frightened until the end of the mummy''s next turn. If the target fails the saving throw by 5 or more, it is also paralyzed for the same duration. A target that succeeds on the saving throw is immune to the Dreadful Glare of all mummies and mummy lords for the next 24 hours.","saveDc":16,"saveAbility":"wis"}],"legendaryActions":[{"name":"Attack","text":"The mummy lord makes one attack with its rotting fist or uses its Dreadful Glare."},{"name":"Blinding Dust","text":"Blinding dust and sand swirls magically around the mummy lord. Each creature within 5 feet of the mummy lord must succeed on a DC 16 Constitution saving throw or be blinded until the end of the creature''s next turn."},{"name":"Blasphemous Word (Costs 2 Actions)","text":"The mummy lord utters a blasphemous word. Each non-undead creature within 10 feet of the mummy lord that can hear the magical utterance must succeed on a DC 16 Constitution saving throw or be stunned until the end of the mummy lord''s next turn."},{"name":"Channel Negative Energy (Costs 2 Actions)","text":"The mummy lord magically unleashes negative energy. Creatures within 60 feet of the mummy lord, including ones behind barriers and around corners, can''t regain hit points until the end of the mummy lord''s next turn."},{"name":"Whirlwind of Sand (Costs 2 Actions)","text":"The mummy lord magically transforms into a whirlwind of sand, moves up to 60 feet, and reverts to its normal form. While in whirlwind form, the mummy lord is immune to all damage, and it can''t be grappled, petrified, knocked prone, restrained, or stunned. Equipment worn or carried by the mummy lord remain in its possession."}],"legendaryCount":3}'),
    ('Nalfeshnee', '/icons/monsters/_mono/N.svg', 'large', 'fiend', '{"name":"Nalfeshnee","size":"large","type":"fiend","ac":18,"hp":184,"speed":{"walk":20,"fly":30},"abilities":{"str":21,"dex":10,"con":22,"int":19,"wis":12,"cha":15},"cr":"13","proficiencyBonus":5,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Natural Armor","hitDice":"16d10 + 96","saves":{"con":11,"int":9,"wis":6,"cha":7},"damageResistances":["Cold","Fire","Lightning","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks"],"damageImmunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":["Truesight 120 ft.","Passive Perception 11"],"languages":["Abyssal","Telepathy 120 ft."],"traits":[{"name":"Magic Resistance","text":"The nalfeshnee has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","text":"The nalfeshnee uses Horror Nimbus if it can. It then makes three attacks: one with its bite and two with its claws."},{"name":"Bite","text":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 32 (5d10 + 5) piercing damage.","attackBonus":10,"reach":"5 ft","damage":"5d10+5","damageType":"piercing"},{"name":"Claw","text":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 15 (3d6 + 5) slashing damage.","attackBonus":10,"reach":"10 ft","damage":"3d6+5","damageType":"slashing"},{"name":"Horror Nimbus (Recharge 5–6)","text":"The nalfeshnee magically emits scintillating, multicolored light. Each creature within 15 feet of the nalfeshnee that can see the light must succeed on a DC 15 Wisdom saving throw or be frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the nalfeshnee''s Horror Nimbus for the next 24 hours.","saveDc":15,"saveAbility":"wis"},{"name":"Teleport","text":"The nalfeshnee magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."}]}'),
    ('Night Hag', '/icons/monsters/_mono/N.svg', 'medium', 'fiend', '{"name":"Night Hag","size":"medium","type":"fiend","ac":17,"hp":112,"speed":{"walk":30},"abilities":{"str":18,"dex":15,"con":16,"int":16,"wis":14,"cha":16},"cr":"5","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Natural Armor","hitDice":"15d8 + 45","skills":[{"name":"Deception","bonus":7},{"name":"Insight","bonus":6},{"name":"Perception","bonus":6},{"name":"Stealth","bonus":6}],"damageResistances":["Cold","Fire","Bludgeoning","Piercing","and Slashing from Nonmagical Attacks that aren''t Silvered"],"conditionImmunities":["Charmed"],"senses":["Darkvision 120 ft.","Passive Perception 16"],"languages":["Abyssal","Common","Infernal","Primordial"],"traits":[{"name":"Innate Spellcasting","text":"The hag''s innate spellcasting ability is Charisma (spell save DC 14, +6 to hit with spell attacks). She can innately cast the following spells, requiring no material components:"},{"name":"Magic Resistance","text":"The hag has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Claws","text":"(Hag Form Only). Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"2d8+4","damageType":"slashing"},{"name":"Change Shape","text":"The hag magically polymorphs into a Small or Medium female humanoid, or back into her true form. Her statistics are the same in each form. Any equipment she is wearing or carrying isn''t transformed. She reverts to her true form if she dies."},{"name":"Etherealness","text":"The hag magically enters the Ethereal Plane from the Material Plane, or vice versa. To do so, the hag must have a heartstone in her possession."},{"name":"Nightmare Haunting (1/Day)","text":"While on the Ethereal Plane, the hag magically touches a sleeping humanoid on the Material Plane. A protection from evil and good spell cast on the target prevents this contact, as does a magic circle. As long as the contact persists, the target has dreadful visions. If these visions last for at least 1 hour, the target gains no benefit from its rest, and its hit point maximum is reduced by 5 (1d10). If this effect reduces the target''s hit point maximum to 0, the target dies, and if the target was evil, its soul is trapped in the hag''s soul bag. The reduction to the target''s hit point maximum lasts until removed by the greater restoration spell or similar magic."}]}'),
    ('Nightmare', '/icons/monsters/_mono/N.svg', 'large', 'fiend', '{"name":"Nightmare","size":"large","type":"fiend","ac":13,"hp":68,"speed":{"walk":60,"fly":90},"abilities":{"str":18,"dex":15,"con":16,"int":10,"wis":13,"cha":15},"cr":"3","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","acNote":"Natural Armor","hitDice":"8d10 + 24","damageImmunities":["Fire"],"senses":["Passive Perception 11"],"languages":["Common  and Infernal but can''t speak"],"traits":[{"name":"Confer Fire Resistance","text":"The nightmare can grant resistance to fire damage to anyone riding it."},{"name":"Illumination","text":"The nightmare sheds bright light in a 10-foot radius and dim light for an additional 10 feet."}],"actions":[{"name":"Hooves","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) bludgeoning damage plus 7 (2d6) fire damage.","attackBonus":6,"reach":"5 ft","damage":"2d8+4","damageType":"bludgeoning"},{"name":"Ethereal Stride","text":"The nightmare and up to three willing creatures within 5 feet of it magically enter the Ethereal Plane from the Material Plane, or vice versa."}]}'),
    ('Noble', '/icons/monsters/_mono/N.svg', 'medium', 'humanoid', '{"name":"Noble","size":"medium","type":"humanoid","ac":15,"hp":9,"speed":{"walk":30},"abilities":{"str":11,"dex":12,"con":11,"int":12,"wis":14,"cha":16},"cr":"1/8","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"any","acNote":"Breastplate","hitDice":"2d8","skills":[{"name":"Deception","bonus":5},{"name":"Insight","bonus":4},{"name":"Persuasion","bonus":5}],"senses":["Passive Perception 12"],"languages":["Any two languages"],"actions":[{"name":"Rapier","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 5 (1d8 + 1) piercing damage.","attackBonus":3,"reach":"5 ft","damage":"1d8+1","damageType":"piercing"}],"reactions":[{"name":"Parry","text":"The noble adds 2 to its AC against one melee attack that would hit it. To do so, the noble must see the attacker and be wielding a melee weapon."}]}'),
    ('Nothic', '/icons/monsters/_mono/N.svg', 'medium', 'aberration', '{"name":"Nothic","size":"medium","type":"aberration","ac":15,"hp":45,"speed":{"walk":30},"abilities":{"str":14,"dex":16,"con":16,"int":13,"wis":10,"cha":8},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"6d8 + 18","skills":[{"name":"Arcana","bonus":3},{"name":"Insight","bonus":4},{"name":"Perception","bonus":2},{"name":"Stealth","bonus":5}],"senses":["Truesight 120 ft.","Passive Perception 12"],"languages":["Undercommon"],"traits":[{"name":"Keen Sight","text":"The nothic has advantage on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Multiattack","text":"The nothic makes two claw attacks."},{"name":"Claw","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) slashing damage.","attackBonus":4,"reach":"5 ft","damage":"1d6+3","damageType":"slashing"},{"name":"Rotting Gaze","text":"The nothic targets one creature it can see within 30 feet of it. The target must succeed on a DC 12 Constitution saving throw against this magic or take 10 (3d6) necrotic damage.","saveDc":12,"saveAbility":"con"},{"name":"Weird Insight","text":"The nothic targets one creature it can see within 30 feet of it. The target must contest its Charisma (Deception) check against the nothic''s Wisdom (Insight) check. If the nothic wins, it magically learns one fact or secret about the target. The target automatically wins if it is immune to being charmed."}]}'),
    ('Ochre Jelly', '/icons/monsters/_mono/O.svg', 'large', 'ooze', '{"name":"Ochre Jelly","size":"large","type":"ooze","ac":8,"hp":45,"speed":{"walk":10,"climb":10},"abilities":{"str":15,"dex":6,"con":14,"int":2,"wis":6,"cha":1},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"6d10 + 12","damageResistances":["Acid"],"damageImmunities":["Lightning","Slashing"],"conditionImmunities":["Blinded","Charmed","Deafened","Exhaustion","Frightened","Prone"],"senses":["Blindsight 60 ft.","Passive Perception 8"],"languages":["--"],"traits":[{"name":"Amorphous","text":"The jelly can move through a space as narrow as 1 inch wide without squeezing."},{"name":"Spider Climb","text":"The jelly can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."}],"actions":[{"name":"Pseudopod","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 9 (2d6 + 2) bludgeoning damage plus 3 (1d6) acid damage.","attackBonus":4,"reach":"5 ft","damage":"2d6+2","damageType":"bludgeoning"}],"reactions":[{"name":"Split","text":"When a jelly that is Medium or larger is subjected to lightning or slashing damage, it splits into two new jellies if it has at least 10 hit points. Each new jelly has hit points equal to half the original jelly''s, rounded down. New jellies are one size smaller than the original jelly."}]}'),
    ('Octopus', '/icons/monsters/_mono/O.svg', 'small', 'beast', '{"name":"Octopus","size":"small","type":"beast","ac":12,"hp":3,"speed":{"walk":5,"swim":30},"abilities":{"str":4,"dex":15,"con":11,"int":3,"wis":10,"cha":4},"cr":"0","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"unaligned","hitDice":"1d6","skills":[{"name":"Perception","bonus":2},{"name":"Stealth","bonus":4}],"senses":["Darkvision 30 ft.","Passive Perception 12"],"languages":["--"],"traits":[{"name":"Hold Breath","text":"While out of water, the octopus can hold its breath for 30 minutes."},{"name":"Underwater Camouflage","text":"The octopus has advantage on Dexterity (Stealth) checks made while underwater."},{"name":"Water Breathing","text":"The octopus can breathe only underwater."}],"actions":[{"name":"Tentacles","text":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 1 bludgeoning damage, and the target is grappled (escape DC 10). Until this grapple ends, the octopus can''t use its tentacles on another target.","attackBonus":4,"reach":"5 ft"},{"name":"Ink Cloud (Recharges after a Short or Long Rest)","text":"A 5-foot-radius cloud of ink extends all around the octopus if it is underwater. The area is heavily obscured for 1 minute, although a significant current can disperse the ink. After releasing the ink, the octopus can use the Dash action as a bonus action."}]}'),
    ('Ogre', '/icons/monsters/_mono/O.svg', 'large', 'giant', '{"name":"Ogre","size":"large","type":"giant","ac":11,"hp":59,"speed":{"walk":40},"abilities":{"str":19,"dex":8,"con":16,"int":5,"wis":7,"cha":7},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Hide Armor","hitDice":"7d10 + 21","senses":["Darkvision 60 ft.","Passive Perception 8"],"languages":["Common","Giant"],"actions":[{"name":"Greatclub","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) bludgeoning damage.","attackBonus":6,"reach":"5 ft","damage":"2d8+4","damageType":"bludgeoning"},{"name":"Javelin","text":"Melee or Ranged Weapon Attack: +6 to hit, reach 5 ft. or range 30/120 ft., one target. Hit: 11 (2d6 + 4) piercing damage.","attackBonus":6,"reach":"5 ft","damage":"2d6+4","damageType":"piercing"}]}'),
    ('Ogre Zombie', '/icons/monsters/_mono/O.svg', 'large', 'undead', '{"name":"Ogre Zombie","size":"large","type":"undead","ac":8,"hp":85,"speed":{"walk":30},"abilities":{"str":19,"dex":6,"con":18,"int":3,"wis":6,"cha":5},"cr":"2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"neutral evil","hitDice":"9d10 + 36","saves":{"wis":0},"damageImmunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":["Darkvision 60 ft.","Passive Perception 8"],"languages":["Understands Common and Giant but can''t speak  them"],"traits":[{"name":"Undead Fortitude","text":"If damage reduces the zombie to 0 hit points, it must make a Constitution saving throw with a DC of 5 + the damage taken, unless the damage is radiant or from a critical hit. On a success, the zombie drops to 1 hit point instead."}],"actions":[{"name":"Morningstar","text":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) bludgeoning damage.","attackBonus":6,"reach":"5 ft","damage":"2d8+4","damageType":"bludgeoning"}]}'),
    ('Oni', '/icons/monsters/_mono/O.svg', 'large', 'giant', '{"name":"Oni","size":"large","type":"giant","ac":16,"hp":110,"speed":{"walk":30,"fly":30},"abilities":{"str":19,"dex":11,"con":16,"int":14,"wis":12,"cha":15},"cr":"7","proficiencyBonus":3,"source":"SRD 5.1, CC-BY-4.0","alignment":"lawful evil","acNote":"Chain Mail","hitDice":"13d10 + 39","saves":{"dex":3,"con":6,"wis":4,"cha":5},"skills":[{"name":"Arcana","bonus":5},{"name":"Deception","bonus":8},{"name":"Perception","bonus":4}],"senses":["Darkvision 60 ft.","Passive Perception 14"],"languages":["Common","Giant"],"traits":[{"name":"Innate Spellcasting","text":"The oni''s innate spellcasting ability is Charisma (spell save DC 13). The oni can innately cast the following spells, requiring no material components:"},{"name":"Magic Weapons","text":"The oni''s weapon attacks are magical."},{"name":"Regeneration","text":"The oni regains 10 hit points at the start of its turn if it has at least 1 hit point."}],"actions":[{"name":"Multiattack","text":"The oni makes two attacks, either with its claws or its glaive."},{"name":"Claw (Oni Form Only)","text":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 8 (1d8 + 4) slashing damage.","attackBonus":7,"reach":"5 ft","damage":"1d8+4","damageType":"slashing"},{"name":"Glaive","text":"Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 15 (2d10 + 4) slashing damage, or 9 (1d10 + 4) slashing damage in Small or Medium form.","attackBonus":7,"reach":"10 ft","damage":"2d10+4","damageType":"slashing"},{"name":"Change Shape","text":"The oni magically polymorphs into a Small or Medium humanoid, into a Large giant, or back into its true form. Other than its size, its statistics are the same in each form. The only equipment that is transformed is its glaive, which shrinks so that it can be wielded in humanoid form. If the oni dies, it reverts to its true form, and its glaive reverts to its normal size."}]}'),
    ('Orc', '/icons/monsters/_mono/O.svg', 'medium', 'humanoid', '{"name":"Orc","size":"medium","type":"humanoid","ac":13,"hp":15,"speed":{"walk":30},"abilities":{"str":16,"dex":12,"con":16,"int":7,"wis":11,"cha":10},"cr":"1/2","proficiencyBonus":2,"source":"SRD 5.1, CC-BY-4.0","alignment":"chaotic evil","acNote":"Hide Armor","hitDice":"2d8 + 6","skills":[{"name":"Intimidation","bonus":2}],"senses":["Darkvision 60 ft.","Passive Perception 10"],"languages":["Common","Orc"],"traits":[{"name":"Aggressive","text":"As a bonus action, the orc can move up to its speed toward a hostile creature that it can see."}],"actions":[{"name":"Greataxe","text":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 9 (1d12 + 3) slashing damage.","attackBonus":5,"reach":"5 ft","damage":"1d12+3","damageType":"slashing"},{"name":"Javelin","text":"Melee or Ranged Weapon Attack: +5 to hit, reach 5 ft. or range 30/120 ft., one target. Hit: 6 (1d6 + 3) piercing damage.","attackBonus":5,"reach":"5 ft","damage":"1d6+3","damageType":"piercing"}]}')
  ) as v(name, image_url, size, ctype, mb)
  where not exists (
    select 1 from public.token_assets t
    where t.owner_id = me and t.token_type = 'monster' and t.name = v.name
  );
end $$;
